window.SAFETY_BANK={docs:{"HSEW-01":"ایمنی فرایند تهیه محلول نیترات آهن","HSEW-02":"ایمنی فرایند تهیه محلول نیتراتی از کاتالیست مستعمل","HSEW-03":"ایمنی فرایند انحلال کیک کربنات و هیدروکسید نیکل","HSEW-04":"ایمنی فرایند انحلال کاتالیست مستعمل پری‌ریفرمینگ","HSEW-05":"ایمنی فرایند بازیابی کیک هیدروکسید نیکل","HSEW-06":"ایمنی فرایند بازیابی نیکل پودری نیتراتی","HSEW-07":"ایمنی فرایند انحلال کاتالیست مستعمل استیم ریفرمینگ","HSEW-08":"ایمنی فرایند انحلال کاتالیست مستعمل نیمه‌فعال","HSEW-09":"ایمنی فرایند حل‌سازی پودر آهن در اتوکلاو","HSEW-13":"ایمنی کار در ارتفاع","HSEW-14":"ایمنی کار گرم","HSEW-15":"ایمنی جوشکاری و برشکاری","HSEW-16":"ایمنی سیلندرهای تحت فشار","HSEW-17":"ایمنی اپراتور جرثقیل سقفی","HSEW-18":"ایمنی نردبان","HSEW-19":"ایمنی تابلو برق","HSEW-20":"ایمنی پست برق","HSEW-21":"ایمنی تعمیرات برق","HSEW-22":"ایمنی تعمیرات مکانیک","HSEW-23":"ایمنی انبار مواد شیمیایی","HSEW-24":"ایمنی حمل دستی بار","HSEW-25":"ایمنی سنگ‌فرز و دریل دستی","HSEW-26":"ایمنی کار با لیفتراک","HSEW-27":"مقابله با حوادث جانی","HSEW-28":"ایمنی، بهداشت و محیط‌زیستی پیمانکاران"},tips:[{t:"آشکارساز LEL آمونیاک",x:"LEL آمونیاک حدود ۱۵٪ حجمی (۱۵۰٬۰۰۰ ppm) است؛ هر ۱٪ LEL معادل حدود ۱۵۰۰ ppm است، یعنی بسیار بالاتر از سطح سمی (IDLH برابر ۳۰۰ ppm). برای حفاظت افراد حسگر الکتروشیمیایی سمی لازم است، نه آشکارساز LEL.",r:"NIOSH / IEC 60079-29-1",g:"A",w:2},{t:"جدول بار جرثقیل",x:"ظرفیت جدول بار به شعاع کار بستگی دارد و با افزایش شعاع شدیداً افت می‌کند. وزن بلوک قلاب، بند و تجهیز آویز باید از ظرفیت کم شود؛ مقایسهٔ فقط وزن بار با ظرفیت، اشتباه رایج برنامهٔ بلندکردن است.",r:"ASME B30.5",d:"HSEW-17",g:"B",w:8},{t:"کمیته‌ی ایمنی مؤثر",x:"کمیته‌ی ایمنی وقتی مؤثر است که تصمیم و اقدام تولید کند: دستور جلسه‌ی مبتنی بر داده، مالک و موعد برای هر مصوبه، پیگیری درصد اقدامات بسته‌شده و حضور نماینده‌ی هر هال. دلیل: کمیته‌ای که فقط گزارش می‌شنود، تشریفاتی است.",r:"ISO 45001 §5.4",g:"C",w:16},{t:"LEL و درصد حجمی",x:"۱۰۰٪ LEL هیدروژن برابر ۴٪ حجمی است، پس ۲۵٪ LEL فقط ۱٪ حجمی است. آلارم‌ها معمولاً در حدود ۱۰ تا ۲۰٪ LEL (هشدار) و ۲۰ تا ۵۰٪ LEL (خطر) تنظیم می‌شوند؛ قابل‌اشتعال بالای ۱۰٪ LEL در فضای بسته طبق OSHA اتمسفر خطرناک است.",r:"OSHA 1910.146 / IEC 60079-29-1",g:"A",w:2},{t:"فاصله سیلندر و استیلن",x:"سیلندر اکسیژن باید از گاز سوخت حداقل ۶ m (۲۰ فوت) فاصله داشته باشد یا دیوار ۱٫۵ m (۵ فوت) با مقاومت آتش نیم‌ساعته بین آنها باشد. استیلن آزاد بالای ۱۵ psig (≈۱ bar) ناپایدار است و ممکن است منفجر شود، پس تنظیم فشار آن نباید بالاتر برود.",r:"OSHA 1926.350(a)(10); OSHA 1910.253(b)(2)",d:"HSEW-16",g:"B",w:1},{t:"سطوح کرک‌پاتریک",x:"مدل کرک‌پاتریک چهار سطح دارد: واکنش، یادگیری، رفتار، نتایج. رضایت و آزمون پایانی (سطح ۱ و ۲) اثربخشی را ثابت نمی‌کنند؛ سطح ۳ را با مشاهده‌ی میدانی چند هفته بعد بسنجید. دلیل: هدف آموزش تغییر رفتار در هال است، نه نمره‌ی آزمون.",r:"Kirkpatrick Model; ISO 45001 §7.2",g:"C",w:16},{t:"نیترات آمونیوم و pH",x:"محلول نیترات آمونیوم در حضور اسید قوی (pH پایین)، آلودگی کلرید یا مواد آلی، و در دمای بالا یا تغلیظ می‌تواند تجزیه گرمازا و در بدترین حالت انفجاری داشته باشد. در واحد بازیابی، pH و دمای تبخیرکننده را کنترل و از خشک‌شدن رسوب جلوگیری کنید.",r:"IChemE / NFPA 400",d:"HSEW-03",g:"A",w:1},{t:"تفکیک عابر و لیفتراک",x:"مؤثرترین کنترل، جداسازی فیزیکی مسیر عابر و لیفتراک (نرده، گذرگاه مجزا) است نه خط‌کشی یا هشدار. تقاطع‌ها به آینه، چراغ هشدار و سرعت محدود نیاز دارند؛ نقاط کور بار حتی راننده ماهر را از دیدن عابر ناتوان می‌کند.",r:"HSE UK HSG136; ISO 3691-1",d:"HSEW-26",g:"B",w:8},{t:"تحلیل سد",x:"تحلیل سد برای هر انرژی یا خطر (مثل اسید داغ) می‌پرسد: چه سدی لازم بود؟ وجود داشت؟ کار کرد؟ چرا شکست خورد؟ دلیل: نتیجه مستقیماً به اقدام اصلاحی در لایه‌ی حفاظتی می‌رسد و تحقیق را از سرزنش فرد به ضعف سیستم می‌برد.",r:"CCPS Incident Investigation; ISO 31010",g:"C",w:12},{t:"سلسله‌مراتب کنترل",x:"طبق ISO 45001 بند ۸٫۱٫۲ ترتیب کنترل: حذف، جایگزینی، کنترل مهندسی و تغییر در کار، کنترل اداری و در نهایت PPE. تبدیل گرد خشک نیکل به خمیر/دوغاب و انتقال بسته، بالاتر از نصب LEV است؛ PPE آخرین خط دفاع است.",r:"ISO 45001 §8.1.2",g:"A",w:11},{t:"ولتاژ باقی‌مانده",x:"خازن‌ها و باس DC درایو VFD پس از قطع برق تا چند دقیقه ولتاژ خطرناک نگه می‌دارند و خاموش‌بودن نمایشگر دلیل تخلیه نیست. زمان انتظار برچسب سازنده (اغلب حدود ۵ دقیقه) باید رعایت و ولتاژ باس با ولت‌متر مناسب اندازه‌گیری شود.",r:"IEC 61800-5-1; NFPA 70E",d:"HSEW-20",g:"B",w:10},{t:"سدها در Bow-tie",x:"در Bow-tie سمت چپِ رویداد بالایی (مثل نشت H2S) سدهای پیشگیرانه و سمت راست سدهای کاهنده‌ی پیامد قرار دارد. هر سد باید مؤثر، مستقل و قابل بازرسی باشد و برای عامل تشدید (مثل دتکتور کالیبره‌نشده) کنترل جدا داشته باشد. دلیل: شمار سد، اثربخشی را تضمین نمی‌کند.",r:"CCPS Bow-tie; ISO 31010",g:"C",w:11},{t:"انفجار گرد و نیکل",x:"انفجار گرد به سوخت، اکسیژن، منبع اشتعال، پخش‌شدن گرد در هوا و محصور بودن نیاز دارد؛ حذف یکی کافی است. نیکل فلزی ریزدانه می‌تواند قابل احتراق باشد، اما اکسید کاملاً اکسیده معمولاً نه؛ این فرض را با آزمون روی نمونه واقعی تأیید کنید.",r:"NFPA 652",g:"A",w:4},{t:"هیدروژن باتری سرب‌اسید",x:"شارژ باتری سرب‌اسید هیدروژن آزاد می‌کند (LEL ≈۴٪) که چون سبک است زیر سقف جمع می‌شود. اتاق شارژ باید تهویهٔ مکش از بالا، فقدان منبع جرقه و ایستگاه شست‌وشوی چشم داشته باشد؛ اتصال کابل را قبل از قطع جریان شارژ نکشید.",r:"OSHA 1910.178(g)",d:"HSEW-26",g:"B",w:1},{t:"کلمات راهنمای HAZOP",x:"در HAZOP هر انحراف از ترکیب کلمه‌ی راهنما و پارامتر ساخته می‌شود: No، More، Less، As well as، Part of، Reverse، Other than؛ مثل «More + Temperature» در اتوکلاو. دلیل: ساختار سیستماتیک مانع می‌شود تیم فقط به خطرهای آشنا فکر کند.",r:"IEC 61882",d:"HSEW-01",g:"C",w:11},{t:"نیکل کربونیل",x:"منواکسید کربن در تماس با نیکل فلزی ریزدانه و فعال از حدود ۵۰ درجه به بالا می‌تواند نیکل کربونیل بسیار سمی و فرار تولید کند. در واحدهای احیا یا کوره با CO یا گاز سنتز، حضور هم‌زمان CO و نیکل فعال را در ارزیابی ریسک و پایش لحاظ کنید.",r:"ACGIH / NIOSH (Nickel carbonyl)",g:"A",w:4},{t:"تروما در آویختگی",x:"فرد ساکن یا بیهوش در هارنس ممکن است ظرف چند دقیقه تا چند ده دقیقه دچار افت برگشت وریدی و خطر مرگ شود. پس نجات باید پیش از کار برنامه‌ریزی شود و انتظار صرف برای اورژانس بیرونی پذیرفته نیست؛ بند ضدتروما زمان می‌خرد.",r:"OSHA 1926.502(d)(20); OSHA SHIB 03-24-2004",d:"HSEW-13",g:"B",w:7},{t:"رابط با پیمانکار",x:"هماهنگی با پیمانکار یعنی ارزیابی ریسک مشترک، یک نقطه‌ی تماس، توجیه ایمنی پیش از کار و کنترل عملیات هم‌زمان (SIMOPS)؛ مثلاً کار گرم کنار واحد آمونیاک در حال بهره‌برداری. دلیل: بیشتر حوادث پیمانکاران در رابط رخ می‌دهد، جایی که طرفین خطر یکدیگر را نمی‌دانند.",r:"ISO 45001 §8.1.4; CCPS RBPS",d:"HSEW-28",g:"C",w:14},{t:"سرعت جذب در LEV",x:"در هود با دهانه ساده، سرعت جذب با فاصله تقریباً به نسبت عکس مجذور فاصله افت می‌کند؛ دو برابر کردن فاصله، سرعت را حدود یک‌چهارم می‌کند. افزودن فلنج، دبی لازم را حدود ۲۵٪ کم می‌کند. هود را تا حد ممکن به منبع نزدیک کنید.",r:"ACGIH Industrial Ventilation Manual",g:"A",w:9},{t:"وظیفهٔ نگهبان بیرونی",x:"نگهبان هرگز برای نجات وارد نمی‌شود؛ فقط ارتباط، شمارش ورودی‌ها، ممانعت از ورود غیرمجاز و فراخوان نجات را بر عهده دارد. طبق NIOSH حدود ۶۰٪ تلفات فضای بسته را نجات‌گران بی‌تجهیز تشکیل می‌دهند؛ وظیفهٔ دیگر نباید حواس او را منحرف کند.",r:"NIOSH 86-110; OSHA 1910.146(i)",g:"B",w:5},{t:"سلسله‌مراتب کنترل",x:"ISO ۴۵۰۰۱ بند ۸.۱.۲ ترتیب را حذف، جایگزینی، کنترل مهندسی، کنترل اداری و در آخر PPE می‌داند. دلیل: PPE فقط فرد را محافظت می‌کند، خطر را در منبع باقی می‌گذارد و خرابی‌اش بی‌صدا و وابسته به رفتار است؛ مثلاً انتقال بسته‌ی اسید بر شیلد و پیش‌بند ارجح است.",r:"ISO 45001 §8.1.2",d:"HSEW-01",g:"C",w:11},{t:"آزمون تناسب ماسک",x:"آزمون تناسب پیش از استفاده و دست‌کم سالی یک‌بار لازم است؛ در روش کمی، ضریب تناسب باید برای نیم‌ماسک دست‌کم ۱۰۰ و برای تمام‌صورت دست‌کم ۵۰۰ باشد. ریش یا مو در لبه آب‌بند تناسب را از بین می‌برد و seal check جایگزین آزمون نیست.",r:"OSHA 1910.134 App. A",g:"A",w:6},{t:"سرعت محیطی دیسک ساب",x:"دیسک با سرعت محیطی بیش از رتبه (معمولاً ۸۰ m/s برای دیسک برش تقویت‌شده) می‌ترکد. v = π·D·n/۶۰؛ دیسک ۱۲۵ mm روی ۱۱۰۰۰ دور حدود ۷۲ m/s است، ولی دیسک ۲۳۰ mm روی همان ماشین حدود ۱۳۲ m/s و بسیار خطرناک است.",r:"EN 12413",d:"HSEW-25",g:"B",w:8},{t:"نظارت سلامت شغلی",x:"برنامه‌ی نظارت سلامت شغلی با پایش مواجهه شروع می‌شود: معاینه‌ی پیش از اشتغال (baseline)، معاینه‌ی دوره‌ای متناسب با خطر (مثل نیکل: پوست و دستگاه تنفس) و تحلیل گروهی نتایج. دلیل: نتیجه‌ی غیرعادی در چند نفر یک هال یعنی کنترل مواجهه شکست خورده، نه صرفاً مشکل فردی.",r:"ILO Technical Guidelines on Health Surveillance; ISO 45001 §9.1",g:"C",w:9},{t:"انواع دستکش EN ISO 374",x:"EN ISO 374-1:2016: Type A دست‌کم ۳۰ دقیقه breakthrough برای ۶ ماده آزمون، Type B برای ۳ ماده و Type C دست‌کم ۱۰ دقیقه برای یک ماده. دستکش Type C برای تماس طولانی با اسید مناسب نیست و فقط پاشش کوتاه را پوشش می‌دهد.",r:"EN ISO 374-1:2016",g:"A",w:6},{t:"بستن رسمی مجوز",x:"بستن مجوز فقط امضای پایان کار نیست؛ گیرنده و صادرکننده باید با هم محل را بازدید کنند و از خروج افراد و ابزار و آمادگی تجهیز مطمئن شوند. ایزولاسیون فقط پس از ابطال رسمی برداشته شود، وگرنه ممکن است کار نیمه‌تمام ناخواسته انرژی‌دار شود.",r:"HSE UK HSG250",g:"B",w:3},{t:"خستگی و عملکرد",x:"بیداری ۱۷ تا ۱۹ ساعت متوالی از نظر عملکرد شناختی تقریباً معادل غلظت الکل خون ۰٫۰۵٪ است و با ادامه‌ی بیداری به حدود ۰٫۱٪ می‌رسد (Williamson و Feyer). دلیل: کار بحرانی مثل LOTO یا مانور اتوکلاو در پایان شیفت‌های طولانی باید محدود شود؛ قهوه جایگزین خواب نیست.",r:"Williamson & Feyer 2000; API RP 755",g:"C",w:16},{t:"ایستگاه شست‌وشوی چشم",x:"ANSI Z358.1: چشم‌شوی دست‌کم ۱٫۵ لیتر/دقیقه (۰٫۴ گالن) به مدت ۱۵ دقیقه، دوش اضطراری دست‌کم ۷۵٫۷ لیتر/دقیقه (۲۰ گالن)، دسترسی بدون مانع در حداکثر ۱۰ ثانیه (حدود ۱۶٫۸ متر) و آب ولرم (حدود ۱۶ تا ۳۸ درجه). برای خورنده‌های قوی نزدیک‌تر نصب کنید.",r:"ANSI/ISEA Z358.1",d:"HSEW-23",g:"A",w:15},{t:"تحویل شیفت مجوز",x:"مجوز با تعویض شیفت خودبه‌خود منتقل نمی‌شود. گیرندهٔ جدید باید همراه تحویل‌دهنده از محل بازدید کند، ایزولاسیون و آزمون گاز را مرور و مجوز را دوباره امضا کند؛ ضعف تحویل شیفت در Piper Alpha (۱۹۸۸) به ۱۶۷ تلفات انجامید.",r:"Cullen Report; HSG250",g:"B",w:3},{t:"ورودی مرور مدیریت",x:"ورودی‌های بند ۹.۳ فقط آمار حادثه نیست: وضعیت اقدامات جلسات قبل، تغییر مسائل داخلی و بیرونی، تحقق اهداف، روند حوادث و عدم‌انطباق‌ها، نتایج پایش و ممیزی، انطباق قانونی، مشارکت کارکنان، کفایت منابع و فرصت‌های بهبود. دلیل: مدیریت ارشد باید درباره‌ی اثربخشی سیستم تصمیم بگیرد.",r:"ISO 45001 §9.3",g:"C",w:13},{t:"فاصله بازرسی مخزن",x:"طبق API 510 فاصله بازرسی داخلی/حین کار مخزن فشار نباید از نصف عمر باقی‌مانده یا ده سال (هر کدام کمتر) بیشتر باشد. عمر باقی‌مانده = (ضخامت اندازه‌گیری‌شده − ضخامت حداقل) ÷ نرخ خوردگی؛ در سرویس اسید، نرخ را از داده واقعی بگیرید.",r:"API 510",g:"A",w:0},{t:"رسوب سولفیدی و H2S",x:"اسیدی‌شدن یا هم‌زدن لجن و رسوبات سولفیدی H2S آزاد می‌کند؛ حد IDLH آن ۱۰۰ ppm است و در غلظت‌های بالا حس بو به‌علت فلج عصب بویایی از کار می‌افتد. بنابراین به بو نباید اعتماد کرد و حسگر شخصی ثابت لازم است.",r:"NIOSH IDLH; OSHA 1910.1000",d:"HSEW-01",g:"B",w:2},{t:"شاخص‌های API ۷۵۴",x:"API RP ۷۵۴ شاخص‌های ایمنی فرایندی را در ۴ سطح می‌بیند: سطح ۱ و ۲ نشت مواد (LOPC) با آستانه‌ی شدت، سطح ۳ چالش با سامانه‌های ایمنی (مثل باز شدن شیر اطمینان)، سطح ۴ انضباط عملیاتی. دلیل: سطوح پایین‌تر هشدار زودتری از پیامد بزرگ‌اند.",r:"API RP 754; CCPS Metrics",g:"C",w:13},{t:"ماسک در جو IDLH",x:"ماسک‌های تصفیه‌کننده هوا (کارتریج) در جو IDLH یا کمبود اکسیژن مجاز نیستند و SCBA فشار-مثبت لازم است. NIOSH Pocket Guide برای H2S فقط هوای رسان/SCBA پیشنهاد می‌کند؛ رطوبت زیاد عمر کارتریج آمونیاک را کم می‌کند، پس برنامه تعویض را بر داده‌های واقعی بنا کنید.",r:"OSHA 1910.134(d) / NIOSH Pocket Guide",g:"A",w:6},{t:"انرژی ذخیره‌شده",x:"ایزولاسیون فقط قطع منبع است؛ فنر، وزنهٔ معلق، فشار محبوس در لوله، خازن و دمای سیال انرژی باقی‌مانده‌اند و باید تخلیه، بلید، مهار مکانیکی یا خنک شوند. مثلاً محلول اسیدی داغ محبوس بین دو شیر هنگام بازکردن فلنج همچنان می‌پاشد.",r:"OSHA 1910.147(d)(5)",d:"HSEW-22",g:"B",w:3},{t:"مبنای LTIFR",x:"LTIFR = (تعداد LTI × ۱٬۰۰۰٬۰۰۰) ÷ ساعت کار انجام‌شده، مبنای رایج بین‌المللی؛ OSHA مبنای ۲۰۰٬۰۰۰ ساعت (۱۰۰ نفر × ۲۰۰۰ ساعت) را به کار می‌برد. دلیل: مقایسه‌ی دو عدد با مبنای متفاوت بی‌معناست؛ مبنا را همیشه کنار شاخص بنویسید.",r:"ILO; OSHA 1904",g:"C",w:13},{t:"گازسنجی فضای بسته",x:"شرایط خطرناک طبق OSHA 1910.146: اکسیژن زیر ۱۹٫۵٪ یا بالای ۲۳٫۵٪ و قابل‌اشتعال بالای ۱۰٪ LEL. ترتیب آزمون: اکسیژن، قابل‌اشتعال، سمی؛ و در چند عمق، چون H2 سبک بالا و H2S سنگین پایین جمع می‌شود.",r:"OSHA 1910.146 / NIOSH",g:"A",w:5},{t:"هیدروژن در مخزن اسید",x:"اسید رقیق روی فولاد یا فلز فعال هیدروژن تولید می‌کند (LEL حدود ۴٪) و حداقل انرژی اشتعال آن کمتر از ۰٫۰۲ mJ است. رسوب و فلز باقی‌مانده پس از تخلیه هم گاز می‌دهند؛ پیش از ورود یا جوشکاری، آزمون LEL و تهویه الزامی است.",r:"NFPA 51B; NFPA 77",d:"HSEW-14",g:"B",w:1},{t:"نقد هاینریش و برد",x:"نسبت‌های هاینریش (۱ به ۲۹ به ۳۰۰، سال ۱۹۳۱) و برد (۱ به ۱۰ به ۳۰ به ۶۰۰) از داده‌ی قدیمی آمده و میان انواع حادثه قابل تعمیم نیست. دلیل: کاهش جراحت‌های جزئی لغزش و افتادن، فاجعه‌ی فرایندی مثل انفجار را پیش‌بینی نمی‌کند؛ شاخص‌های ایمنی فرایندی جدا لازم است.",r:"Heinrich 1931; Bird 1969; CCPS",g:"C",w:12},{t:"کلمه هشدار و H350",x:"در GHS فقط دو کلمه هشدار هست: «خطر» برای مخاطرات شدیدتر و «هشدار» برای کم‌شدت‌تر؛ اگر «خطر» به کار رود «هشدار» حذف می‌شود. H350 یعنی سرطان‌زایی رده ۱A/۱B و H351 یعنی مشکوک (رده ۲)؛ اختلاف دو SDS یعنی طبقه‌بندی متفاوت و باید پیگیری شود.",r:"GHS Purple Book",g:"A",w:6},{t:"سه‌مرحله‌ای ISO ۱۲۱۰۰",x:"ISO ۱۲۱۰۰ به ترتیب این مراحل را می‌گذارد: طراحی ذاتاً ایمن، سپس حفاظ و تدابیر حفاظتی تکمیلی، سپس اطلاعات برای استفاده (علائم و آموزش). علامت و آموزش کم‌اثرترین لایه‌اند و جایگزین حفاظ فیزیکی نمی‌شوند.",r:"ISO 12100",d:"HSEW-22",g:"B",w:8},{t:"شرایط IPL",x:"لایه‌ی حفاظتی مستقل (IPL) باید از رویداد آغازگر و سایر IPLها مستقل، مشخص، قابل‌اتکا و قابل ممیزی باشد. دلیل: اگر آلارم و کنترل‌کننده از یک ترنسمیتر مشترک استفاده کنند، یک خرابی هر دو را از کار می‌اندازد و نباید دوبار اعتبار بگیرند.",r:"CCPS LOPA",g:"C",w:11},{t:"Kst و کلاس St",x:"Kst = (dP/dt)max × V^(1/3) شدت انفجار گرد را مستقل از حجم آزمون بیان می‌کند: St1 تا ۲۰۰، St2 تا ۳۰۰ و St3 بالای ۳۰۰ bar·m/s. Pmax فشار حداکثر انفجار است. هر دو برای طراحی دریچه انفجار لازم‌اند.",r:"NFPA 68 / EN 14034",g:"A",w:4},{t:"قفل‌گذاری گروهی",x:"در قفل گروهی هر نفر قفل شخصی خود را روی هسپ مشترک می‌زند و کلیدش فقط نزد خودش است. بدین‌ترتیب تا آخرین نفر کارش را تمام نکند انرژی بازنمی‌گردد؛ قفل واحد یک نفر برای کل گروه یعنی ایمنی همه به حافظهٔ او وابسته است.",r:"OSHA 1910.147(f)(3)",d:"HSEW-22",g:"B",w:3},{t:"تدارک و پیمانکار",x:"بند ۸.۱.۴ ایزو ۴۵۰۰۱ ایجاب می‌کند خطرهای ناشی از فعالیت پیمانکار بر سازمان و برعکس هماهنگ شود و معیارهای صلاحیت HSE پیش از انتخاب پیمانکار اعمال گردد. دلیل: پس از شروع کار، حذف پیمانکار ناصالح دشوار و پرهزینه است.",r:"ISO 45001 §8.1.4",d:"HSEW-28",g:"C",w:14},{t:"حد مه اسید و استانداردها",x:"حد اسید سولفوریک در OSHA PEL برابر ۱ mg/m³ و در ACGIH TLV برابر ۰٫۲ mg/m³ (کسر توراسیک) است. استانداردها تفاوت دارند، پس منبع حد را در گزارش مشخص و برای تصمیم‌گیری، محتاطانه‌تر را مبنا کنید. TLV اسید نیتریک: TWA برابر ۲ و STEL برابر ۴ ppm.",r:"OSHA 1910.1000 Z-1 / ACGIH TLV",d:"HSEW-01",g:"A",w:9},{t:"جنس بند در اسید",x:"نایلون در برابر اسیدها تخریب می‌شود و پلی‌استر در برابر قلیاها؛ در تالار اسیدی بند پلی‌استر مناسب‌تر است (البته نه در برابر اسید غلیظ داغ). بند آلوده به پاشش اسید حتی با ظاهر سالم باید از خدمت خارج و بررسی شود.",r:"ASME B30.9; OSHA 1910.184(i)",d:"HSEW-17",g:"B",w:8},{t:"مدل HFACS",x:"HFACS چهار سطح دارد: اعمال ناایمن، پیش‌شرط‌های اعمال ناایمن، نظارت ناایمن و تأثیرات سازمانی. دلیل: مانع توقف تحقیق در «خطای اپراتور» می‌شود و نشان می‌دهد چرا آن عمل ممکن شد؛ مثلاً سرپرستی که اضافه‌کاری متوالی را برنامه‌ریزی کرده است.",r:"Wiegmann & Shappell HFACS",g:"C",w:16},{t:"مسمومیت حسگر کاتالیستی",x:"حسگر کاتالیستی (پلیستور) با سیلیکون، سرب، H2S یا ترکیبات هالوژنه مسموم و کم‌حساس می‌شود و به اکسیژن کافی نیاز دارد، بی‌آنکه لزوماً خرابی نشان دهد. فقط تست با گاز این افت را آشکار می‌کند؛ از اسپری و درزگیر سیلیکونی کنار حسگر بپرهیزید.",r:"IEC 60079-29-1 / داده سازنده",g:"A",w:2},{t:"تهویه فضای بسته",x:"تهویه جایگزین آزمون نیست؛ هوا باید از منبع پاک و دور از اگزوز وارد شود و پایش تا پایان کار ادامه یابد، چون واکنش اسید با رسوب ممکن است گاز تولید کند. توقف فن یا بالا رفتن آلارم باید به خروج فوری ورودی‌ها منجر شود.",r:"OSHA 1910.146",d:"HSEW-01",g:"B",w:5},{t:"PFD و RRF",x:"ضریب کاهش ریسک RRF = ۱/PFD؛ IPL با PFD برابر ۰٫۰۱ یعنی RRF برابر ۱۰۰. فرکانس کاهش‌یافته = فرکانس رویداد آغازگر × حاصل‌ضرب PFDها؛ مثلاً ۰٫۱ × ۰٫۱ × ۰٫۰۱ = ۰٫۰۰۰۱ در سال. دلیل: لایه‌ها ضرب می‌شوند، نه جمع.",r:"CCPS LOPA",g:"C",w:11},{t:"دیسک انفجاری در اسید",x:"در سرویس خورنده دیسک انفجاری زیر شیر اطمینان قرار می‌گیرد تا شیر با اسید تماس نداشته باشد. فضای بین آن‌ها باید گیج و دریچه تخلیه داشته باشد، چون فشار محبوس از نشتی دیسک به فشار ترکیدن اضافه می‌شود و حفاظت را مختل می‌کند.",r:"ASME BPVC VIII-1 / API 520",g:"A",w:0},{t:"فیوم جوش Cr و Ni",x:"جوش استنلس‌استیل و آلیاژهای نیکل‌دار Cr(VI) و ترکیبات نیکل تولید می‌کند؛ PEL کروم شش‌ظرفیتی OSHA برابر ۵ µg/m³ و ترکیبات نیکل در IARC گروه ۱ است. نمونه‌برداری داخل کلاه جوشکار و LEV نزدیک قوس مؤثرتر از تهویهٔ عمومی است.",r:"OSHA 1910.1026; IARC Vol.100C",d:"HSEW-15",g:"B",w:1},{t:"حفظ شواهد",x:"شواهد را به ترتیب فرّار بودن جمع کنید: لاگ DCS و دتکتور (قابل بازنویسی)، موقعیت شیرها و کلیدها، عکس، سپس نمونه و قطعات؛ پیش از بازگرداندن تجهیز به سرویس مستندسازی کنید. دلیل: بازنویسی لاگ یا تمیزکاری، شواهد علت را برای همیشه از بین می‌برد.",r:"CCPS Incident Investigation",d:"HSEW-27",g:"C",w:12},{t:"نجات در محیط H2S",x:"در غلظت چند صد ppm، فرد با چند نفس بیهوش می‌شود و بیشترین تلفات از نجات‌گرانِ بدون تجهیزات تنفسی است. نجات فقط با SCBA یا هوای رسان، سیستم بازیابی (طناب/سه‌پایه) و تیم آموزش‌دیده؛ ورود شتاب‌زده ممنوع است.",r:"OSHA 1910.146 / 1910.134",g:"A",w:2},{t:"لایه‌بندی گازها",x:"گازها در فضای بسته لایه‌بندی می‌شوند: آمونیاک (چگالی بخار ≈۰٫۶) بالا و H2S (≈۱٫۲) و CO2 (≈۱٫۵) پایین جمع می‌شوند. پروب باید در بالا، وسط و پایین و با زمان پاسخ کافی بخواند؛ آزمون فقط کنار دریچه حفرهٔ ته مخزن را نشان نمی‌دهد.",r:"NIOSH Pocket Guide; OSHA 1910.146",d:"HSEW-01",g:"B",w:5},{t:"مشارکت کارکنان",x:"ISO ۴۵۰۰۱ بند ۵.۴ مشورت و مشارکت کارکنانِ غیرمدیریتی را در شناسایی خطر، ارزیابی ریسک و بررسی حوادث می‌خواهد و سازمان باید موانعی مثل ترس از تنبیه و مشکل زبانی را بردارد. دلیل: اپراتور هال، خطرهای واقعی را زودتر از دفتر مدیریت می‌بیند.",r:"ISO 45001 §5.4",g:"C",w:16},{t:"فشار و شیر اطمینان",x:"شیر اطمینان باید حداکثر در MAWP باز شود و در حالت غیرحریق با یک شیر، افزایش فشار هنگام تخلیه نباید از ۱۰٪ بالاتر از MAWP بگذرد. فشار هیدروتست یا فشار ترکیدن، معیار پذیرش رویداد فشار نیست.",r:"ASME BPVC Section VIII Div.1",g:"A",w:0},{t:"محدودهٔ مجاز اکسیژن",x:"طبق OSHA اتمسفر کمبود اکسیژن زیر ۱۹٫۵٪ و غنی‌شده بالای ۲۳٫۵٪ حجمی است. غنی‌شدگی (مثلاً نشت اکسیژن از شیلنگ جوشکاری) خطر آتش شدید دارد، و افت حتی کوچک نشانهٔ جابه‌جایی توسط گاز دیگری است که ممکن است خودش سمی باشد.",r:"OSHA 1910.146(b)",g:"B",w:5},{t:"تمرین میزی یا مقیاس کامل",x:"تمرین میزی تصمیم‌گیری و هماهنگی را کم‌هزینه می‌سنجد ولی توان فیزیکی (استفاده از تجهیز، تخلیه) را نه. مسیر پلکانی: آموزش، تمرین میزی، عملکردی، سپس مقیاس کامل. دلیل: مقیاس کامل بدون آمادگی قبلی خطرناک و پرهزینه است و ضعف‌ها را دیر نشان می‌دهد.",r:"FEMA HSEEP",d:"HSEW-27",g:"C",w:15},{t:"اسید نیتریک اکسیدکننده",x:"اسید نیتریک غلیظ فقط خورنده نیست، اکسیدکننده قوی هم هست و با مواد آلی (چوب، پارچه، حلال، روغن) واکنش گرمازا داده و می‌تواند آتش یا انفجار ایجاد کند. ذخیره را از مواد آلی جدا کنید و از پالت چوبی زیر آن استفاده نکنید.",r:"NFPA 400 / SDS",d:"HSEW-23",g:"A",w:0},{t:"انرژی قوس برق",x:"مرز قوس برق فاصله‌ای است که انرژی تابشی به ۱٫۲ cal/cm² (حدود ۵ J/cm²) می‌رسد، یعنی آستانهٔ سوختگی درجه دو قابل‌ترمیم. این مقدار از مطالعهٔ قوس برق تجهیز به‌دست می‌آید؛ جداول دسته‌بندی PPE فقط تقریبی‌اند و شرایط خاص دارند.",r:"NFPA 70E §130.5",d:"HSEW-19",g:"B",w:10},{t:"تله‌ی ماتریس ریسک",x:"ضرب دو رتبه‌ی ترتیبی در ماتریس ریسک عدد کاذب می‌سازد: احتمال ۵ × شدت ۱ با احتمال ۱ × شدت ۵ هر دو ۵ می‌شوند، اما جراحت جزئی مکرر با مرگ نادر هم‌ارز نیست. دلیل: پیامدهای شدید را باید با قاعده‌ی جداگانه بررسی کرد.",r:"ISO 31010; ISO 45001 §6.1.2",g:"C",w:11},{t:"کار گرم روی مخزن اسید",x:"مخزن تخلیه‌شده‌ای که اسید رقیق داشته، ممکن است هیدروژن ناشی از واکنش اسید با جداره فولادی را در نقاط مرده نگه دارد. پیش از جوشکاری: شست‌وشو، تهویه و گازسنجی LEL در چند نقطه؛ «خالی بودن» به معنای ایمن بودن نیست.",r:"NFPA 51B",d:"HSEW-14",g:"A",w:1},{t:"دوبل‌بلاک و بلید",x:"در DBB دو شیر بسته با یک خروجی بلید میانی، نشتی شیر را آشکار می‌کند؛ ولی شیر هنگام کار هم می‌تواند نشت کند و بلید بسته یا مسدود ایزولاسیون را بی‌اعتبار می‌کند. برای ورود به مخزن یا بازکردن خط خطرناک، ایزولاسیون فیزیکی (بلایند) قابل‌اعتمادتر است.",r:"HSE UK HSG253",d:"HSEW-22",g:"B",w:3},{t:"فرهنگ عادلانه",x:"فرهنگ عادلانه سه رفتار را متفاوت پاسخ می‌دهد: خطای انسانی (حمایت و اصلاح سیستم)، رفتار پرخطر (coaching) و رفتار بی‌پروا (اقدام انضباطی). در آزمون جایگزینی می‌پرسید: فرد دیگری در همان شرایط همین کار را می‌کرد؟ دلیل: تنبیه خطا گزارش‌دهی را می‌کُشد.",r:"Reason (Managing the Risks of Organizational Accidents)",g:"C",w:12},{t:"پایش زیستی نیکل",x:"نیکل ادرار برای نیکل محلول شاخص مناسبی است و نمونه پایان شیفت/پایان هفته کاری معنادارتر است، چون نیمه‌عمر آن در حد ساعت تا یکی دو روز است؛ اما جذب ذرات نامحلول (اکسید) را خوب نشان نمی‌دهد. نمونه صبح پس از تعطیلی، مواجهه را کم‌نمایی می‌کند.",r:"اصول پایش زیستی؛ ATSDR Toxicological Profile for Nickel",g:"A",w:4},{t:"معادلهٔ NIOSH بلندکردن",x:"RWL = ۲۳ kg × HM × VM × DM × AM × FM × CM که ۲۳ kg حد شرایط ایده‌آل است و LI برابر بار تقسیم بر RWL. فاصلهٔ افقی بار از بدن اثر زیادی دارد: HM = ۲۵/H (برحسب cm)؛ با ۵۰ cm ظرفیت نصف می‌شود و LI بالای ۱ خطر افزایش‌یافته است.",r:"NIOSH Lifting Equation 94-110",d:"HSEW-24",g:"B",w:8},{t:"محدودیت پنج‌چرا",x:"پنج‌چرا خطی است و به قضاوت تحلیلگر بستگی دارد؛ دو تیم ممکن است به ریشه‌های متفاوت برسند و زنجیره اغلب روی «خطای انسانی» متوقف می‌شود. دلیل: رویدادهای صنعتی چندعلتی‌اند؛ آن را با تحلیل سد، درخت خطا یا ایشیکاوا تکمیل و علل را با شواهد راستی‌آزمایی کنید.",r:"CCPS Incident Investigation; ISO 45001 §10.2",g:"C",w:12},{t:"آمونیاک و هیپوکلریت",x:"آمیختن آمونیاک یا محلول‌های آمونیاکی با وایتکس/هیپوکلریت (مثلاً هنگام نظافت) کلرآمین‌های سمی تولید می‌کند که ریه را تحریک می‌کنند. شوینده‌های حاوی کلر را از فهرست مجاز نزدیک واحد آمونیاک حذف و در ماتریس ناسازگاری ثبت کنید.",r:"NIOSH / SDS",d:"HSEW-23",g:"A",w:2},{t:"زاویهٔ بند و کشش",x:"کشش هر شاخهٔ بند دوشاخه = W / (۲ sinθ) که θ زاویه با افق است: در ۶۰° حدود ۰٫۵۸ W، در ۴۵° حدود ۰٫۷۱ W و در ۳۰° برابر W. زاویهٔ کمتر از ۳۰° معمولاً اجتناب می‌شود، چون کشش بدون تغییر ظاهر بار به‌سرعت بالا می‌رود.",r:"ASME B30.9; OSHA 1910.184",d:"HSEW-17",g:"B",w:8},{t:"آزمون طرح اضطراری",x:"بند ۸.۲ ایزو ۴۵۰۰۱ می‌خواهد پاسخ اضطراری در بازه‌های برنامه‌ریزی‌شده آزمایش و پس از تمرین و پس از رویداد واقعی بازنگری شود. دلیل: طرح آزمون‌نشده فقط یک فرض است؛ ضعف‌هایی مثل ارتباط ناکارآمد یا مسیر مسدود فقط در تمرین آشکار می‌شود.",r:"ISO 45001 §8.2",d:"HSEW-27",g:"C",w:15},{t:"تهویه رقیق‌کننده یا موضعی",x:"تهویه رقیق‌کننده برای گرد یا مه سرطان‌زا با منبع متمرکز مناسب نیست، چون غلظت منطقه تنفس نزدیک منبع را پایین نمی‌آورد. از گرفتن در منبع (LEV) و آزمون دوره‌ای عملکرد استفاده کنید؛ در بریتانیا COSHH حداکثر فاصله آزمون را ۱۴ ماه می‌داند.",r:"ACGIH IVM / UK COSHH Reg. 9, HSG258",g:"A",w:9},{t:"بلندکردن تاندم",x:"در بلندکردن با دو جرثقیل، سهم بار هر کدام به‌دلیل تفاوت شعاع، سرعت و انحراف طناب نابرابر می‌شود. برنامهٔ مهندسی‌شده، سرپرست بلندکردن و کاهش مجاز ظرفیت هر جرثقیل لازم است؛ استفاده از ۱۰۰٪ ظرفیت هر دو پذیرفته نیست.",r:"ASME B30.5; ASME B30.9",d:"HSEW-17",g:"B",w:8},{t:"نقص RPN در FMEA",x:"در FMEA مقدار RPN = شدت × وقوع × کشف‌پذیری است، اما شدت بالا با RPN پایین پنهان می‌ماند: ۹×۲×۲ = ۳۶ کمتر از ۳×۶×۵ = ۹۰ است. دلیل: ضرب، شدت را رقیق می‌کند؛ روش Action Priority (AIAG-VDA) ابتدا شدت را در نظر می‌گیرد.",r:"AIAG-VDA FMEA 2019; IEC 60812",g:"C",w:11},{t:"عوارض تأخیری NO2",x:"نیتروژن‌اکسیدها (دود قهوه‌ای واکنش اسید نیتریک با فلز) ممکن است در لحظه علائم شدید ندهند، اما ادم ریوی چند ساعت تا یک–دو روز بعد ظاهر می‌شود. فرد در معرض را حتی بدون علامت باید تحت مراقبت پزشکی نگه داشت.",r:"NIOSH / ACGIH (نیتروژن دی‌اکسید)",d:"HSEW-01",g:"A",w:0},{t:"نرخ تبادل نویز",x:"OSHA با آستانهٔ ۹۰ dBA برای ۸ ساعت و نرخ تبادل ۵ dB کار می‌کند، اما NIOSH با REL برابر ۸۵ dBA و نرخ ۳ dB؛ مثلاً ۹۱ dBA طبق NIOSH فقط ۲ ساعت مجاز است. نرخ ۳ dB با اصل برابری انرژی سازگار و محافظ‌تر است.",r:"OSHA 1910.95; NIOSH 98-126",g:"B",w:8},{t:"محل تجمع",x:"محل تجمع در نشت سمی (آمونیاک، H2S) باید بالادست یا عمود بر باد و خارج از شعاع پخش باشد، با بادنمای قابل‌دیدن و دست‌کم یک نقطه‌ی جایگزین. دلیل: باد عوض می‌شود و H2S سنگین‌تر از هواست (چگالی نسبی حدود ۱٫۲) و در گودال‌ها جمع می‌شود.",r:"CCPS ERP; NIOSH H2S",d:"HSEW-27",g:"C",w:15},{t:"نیترات و مواد قابل‌اشتعال",x:"پارچه، دستکش، چوب یا کاغذ آغشته به محلول نیترات آهن پس از خشک‌شدن، مانند سوختی با اکسیدکننده درونی رفتار می‌کند و با شعله یا اصطکاک شدید می‌سوزد و دشوار خاموش می‌شود. نشتی و لباس آلوده را بلافاصله پاک و جمع‌آوری کنید.",r:"NFPA 400",d:"HSEW-02",g:"A",w:1},{t:"WLL و ضریب طراحی",x:"WLL حد کار مجاز است نه حد گسیختگی؛ ضریب طراحی رایج برای زنجیر آلیاژی ۴:۱ و برای طناب فولادی و بند نواری ۵:۱ است. WLL فقط برای حالت اتصال و زاویهٔ مشخص معتبر است و ضربه یا بار پویا حاشیهٔ ایمنی را سریع می‌خورد.",r:"ASME B30.9",d:"HSEW-17",g:"B",w:8},{t:"بازسازی خط زمانی",x:"خط زمانی را مدت‌ها پیش از لحظه‌ی رویداد آغاز کنید: تعمیرات اخیر، تغییر تنظیمات، تحویل شیفت و آلارم‌های ردشده. داده‌ها را از منابع مستقل (DCS، دتکتور، شاهد) تطبیق دهید و واقعیت را از استنباط جدا کنید. دلیل: ریشه‌ی بسیاری از حوادث ساعت‌ها یا روزها قبل کاشته شده است.",r:"CCPS Incident Investigation",g:"C",w:12},{t:"خستگی بویایی H2S",x:"بوی تخم‌مرغ‌گندیده H2S در کسری از ppm حس می‌شود، اما از حدود ۱۰۰ ppm به بالا حس بویایی فلج می‌شود و فرد خطر را «نمی‌یابد». IDLH آن ۱۰۰ ppm است؛ بو هرگز معیار ایمنی نیست و تنها آشکارساز معتبر تصمیم‌ساز است.",r:"NIOSH Pocket Guide (H2S)",g:"A",w:2},{t:"راستی‌آزمایی ایزولاسیون",x:"پس از قفل‌گذاری باید تلاش برای راه‌اندازی (try-out) و در برق آزمون ولتاژ انجام شود، چون برچسب یا موقعیت دکمه ثابت نمی‌کند انرژی صفر است. OSHA این راستی‌آزمایی را پیش از شروع کار می‌خواهد؛ پس از آزمون، کنترل‌ها باید به حالت خاموش برگردند.",r:"OSHA 1910.147(d)(6)",d:"HSEW-22",g:"B",w:3},{t:"نرمال‌سازی انحراف",x:"نرمال‌سازی انحراف (وان، چلنجر): انحراف از رویه که بدون پیامد تکرار شود تدریجاً عادی می‌شود، مثل قفل نکردن «سریع» هنگام رفع گرفتگی. دلیل: نبود حادثه به معنای ایمنی نیست؛ پرسیدن «چرا رویه رعایت نمی‌شود» و ممیزی میدانی لازم است.",r:"Vaughan 1996; CCPS RBPS",g:"C",w:12},{t:"TWA و STEL",x:"TWA میانگین ۸ ساعته و STEL میانگین ۱۵ دقیقه‌ای است که حداکثر چهار بار در شیفت و با فاصله دست‌کم ۶۰ دقیقه مجاز است. اگر ماده STEL ندارد، ACGIH اجازه می‌دهد نوسان تا ۳ برابر TLV-TWA در مجموع حداکثر ۳۰ دقیقه و هرگز بیش از ۵ برابر رخ دهد.",r:"ACGIH TLV (Excursion Limits)",g:"A",w:9},{t:"قفل حفاظ اینترلاک",x:"اگر ماشین پس از قطع مثلاً ۴۰ ثانیه می‌چرخد و حفاظ در ۳ ثانیه باز می‌شود، اینترلاک ساده بی‌فایده است؛ باید قفل حفاظ (guard locking) یا پایش توقف کامل به کار رود. دور زدن اینترلاک با آهنربا یا شنت باید در طراحی دشوار شود.",r:"ISO 14119",d:"HSEW-22",g:"B",w:8},{t:"شاخص پیشرو و پسرو",x:"شاخص پسرو (LTI) پس از آسیب اندازه گرفته می‌شود؛ شاخص پیشرو وضعیت کنترل‌ها را پیش از حادثه می‌سنجد: درصد آزمون به‌موقع دتکتورها، اقدامات عقب‌افتاده، کیفیت ممیزی مجوز کار، گزارش شبه‌حادثه. دلیل: زودترین هشدار از خرابی کنترل‌هاست، نه از زخمی شدن کارگر.",r:"ISO 45001 §9.1; HSE HSG254",g:"C",w:13},{t:"راهبرد ارزیابی مواجهه",x:"در راهبرد AIHA، گروه‌های مواجهه مشابه (SEG) با نمونه‌برداری شخصی در منطقه تنفس ارزیابی می‌شوند و تصمیم بر پایه صدک ۹۵ توزیع لگ‌نرمال است، نه میانگین. میانگین کمتر از حد با پراکندگی (GSD) بالا هنوز می‌تواند غیرقابل‌قبول باشد.",r:"AIHA, A Strategy for Assessing and Managing Occupational Exposures",g:"A",w:9},{t:"محرک‌های بازرسی لیفت",x:"بازرسی سه سطح دارد: پیش از هر استفاده، دوره‌ای حداقل هر ۱۲ ماه (برای بند طبق OSHA) و ویژه پس از تعمیر، ضربه، اضافه‌بار یا تماس با حرارت و مواد شیمیایی. تجهیز مردود باید برچسب‌گذاری و فیزیکی از خدمت خارج شود.",r:"OSHA 1910.184(d); ASME B30.9",d:"HSEW-17",g:"B",w:8},{t:"اعتبار نقشه در HAZOP",x:"کیفیت HAZOP از نقشه‌ی ورودی بیشتر نمی‌شود. اگر P&ID وجود ندارد یا قدیمی است، ابتدا با پیمایش میدانی نقشه‌ی as-built تهیه و تأیید کنید. دلیل: شیر، خط کنارگذر یا ابزار دقیقی که روی نقشه نیست هرگز بررسی نمی‌شود.",r:"IEC 61882; CCPS RBPS",d:"HSEW-01",g:"C",w:11},{t:"رقیق‌سازی اسید سولفوریک",x:"همیشه اسید را به آب بیفزایید، نه برعکس: آب سبک‌تر روی اسید غلیظ می‌ماند و گرمای رقیق‌سازی در لایه کوچکی آزاد می‌شود؛ آب موضعاً می‌جوشد و می‌پاشد. دمای تحمل مخزن و لوله پلیمری را هم کنترل کنید، نه فقط غلظت.",r:"CCPS / SDS اسید سولفوریک",d:"HSEW-01",g:"A",w:0},{t:"نجات و بازیابی",x:"برای ورود عمودی عمیق‌تر از ۱٫۵ m (۵ فوت) باید دستگاه بازیابی مکانیکی (سه‌پایه و وینچ) آماده باشد و زمان پاسخ تیم نجات باید با شدت خطر هم‌خوان باشد؛ در اتمسفر IDLH دقایق تعیین‌کننده است. بازیابی غیرورودی با طناب سریع‌تر است و قربانی دوم نمی‌سازد.",r:"OSHA 1910.146(k)",g:"B",w:5},{t:"صفر LTI و اعداد کوچک",x:"صفر LTI لزوماً ایمنی نیست: با ساعت کار کم، رویداد در بیشتر سال‌ها اتفاقی هم رخ نمی‌دهد؛ با ۱۵۰٬۰۰۰ ساعت و LTIFR برابر ۳، احتمال صفر LTI در یک سال حدود ۶۴٪ است. دلیل: اعداد کوچک نوسان تصادفی دارند؛ از میانگین متحرک و شاخص‌های پیشرو کمک بگیرید.",r:"Poisson statistics; CCPS Metrics",g:"C",w:13},{t:"شیفت غیرمعمول",x:"حد ۸ ساعته برای شیفت ۱۲ ساعته باید تعدیل شود: مدل Brief & Scala ضریب (۸/h)×((۲۴−h)/۱۶) می‌دهد که برای h=۱۲ برابر ۰٫۵ است. شیفت بلند هم مواجهه بیشتر و هم زمان ریکاوری کمتر دارد.",r:"Brief & Scala (1975) / ACGIH TLV Introduction",g:"A",w:9},{t:"مثلث پایداری لیفتراک",x:"لیفتراک روی سه نقطه (دو چرخ جلو و محور فرمان عقب) معلق است و مرکز ثقل ترکیبی لیفتراک و بار باید داخل مثلث بماند. پلاک ظرفیت برای مرکز بار استاندارد ۵۰۰ mm است؛ مرکز بار بلندتر، ارتفاع بیشتر یا الحاقات ظرفیت را کم می‌کنند.",r:"OSHA 1910.178; ANSI/ITSDF B56.1",d:"HSEW-26",g:"B",w:8},{t:"محرک‌های بازنگری ریسک",x:"بازنگری ثبت ریسک را به رویداد گره بزنید: حادثه یا شبه‌حادثه، MOC، ماده یا تجهیز جدید، یافته‌ی ممیزی، تغییر قانون؛ OSHA PSM بازنگری PHA را دست‌کم هر ۵ سال می‌خواهد. دلیل: ریسک با تغییر فرایند عوض می‌شود، نه با تقویم.",r:"ISO 45001 §6.1.2; OSHA 1910.119(e)(6)",g:"C",w:11},{t:"پسماند اسید نیتریک",x:"ریختن اسید نیتریک در ظرف پسماند حاوی حلال یا مواد آلی (استون، الکل) واکنش گرمازای خودشتاب با تولید گاز دارد و ظرف دربسته می‌ترکد. برای پسماند نیتریک ظرف جداگانه، برچسب‌دار و با درپوش دارای تنفس استفاده کنید.",r:"Prudent Practices in the Laboratory (NRC)",d:"HSEW-23",g:"A",w:0},{t:"فضای آزاد سقوط",x:"فضای لازم = سقوط آزاد + کشش جاذب (حداکثر ۱٫۰۷ m در OSHA) + جابه‌جایی حلقهٔ D (≈۰٫۳ m) + فاصلهٔ حلقه تا پا (≈۱٫۵ m) + حاشیه (≈۰٫۹ m). برای بند ۱٫۸ m متصل هم‌سطح پا حدود ۵٫۶ m لازم است؛ کمتر از آن یعنی برخورد با کف.",r:"OSHA 1926.502(d)(16); ANSI Z359.13",d:"HSEW-13",g:"B",w:7},{t:"ساختار ICS",x:"ICS ساختار ماژولار دارد: فرمانده‌ی حادثه و بخش‌های عملیات، برنامه‌ریزی، لجستیک و مالی/اداری؛ افسر ایمنی، اطلاع‌رسانی و رابط زیر نظر فرمانده‌اند. دامنه‌ی کنترل مطلوب ۳ تا ۷ نفر و بهینه ۵ است. دلیل: بیش از آن، فرمانده کنترل را از دست می‌دهد.",r:"FEMA ICS-100",d:"HSEW-27",g:"C",w:15},{t:"طبقه‌بندی سرطان‌زایی نیکل",x:"IARC ترکیبات نیکل را گروه ۱ (سرطان‌زای انسانی) و نیکل فلزی را گروه ۲B می‌داند؛ ACGIH نیز برای نیکل عنصری، ترکیبات محلول و نامحلول TLV جداگانه (کسر قابل استنشاق) دارد. حد نیکل فلزی را نمی‌توان به کربنات یا هیدروکسید تعمیم داد.",r:"IARC Monographs 100C / ACGIH TLV",g:"A",w:4},{t:"درجهٔ حفاظت IP",x:"در IP، رقم اول گردوغبار و رقم دوم آب است؛ IP67 (غوطه‌وری موقت) تضمین‌کنندهٔ مقاومت در برابر جت پرفشار نیست چون آزمون‌ها سلسله‌مراتبی نیستند. IP دربارهٔ خوردگی اسیدی هم چیزی نمی‌گوید؛ در تالار اسید جنس بدنه و واشر نیز باید بررسی شود.",r:"IEC 60529",d:"HSEW-19",g:"B",w:10},{t:"اصل ALARP",x:"در ALARP ریسک ناحیه‌ی تحمل‌پذیر باید تا جایی کاهش یابد که هزینه‌ی اقدام به‌طور فاحش نامتناسب با فایده باشد (HSE بریتانیا). دلیل: «زیر خط قرمز بودن» کافی نیست؛ اقدام ارزان و مؤثر باید اجرا شود حتی اگر ریسک تحمل‌پذیر باشد.",r:"UK HSE R2P2 (ALARP)",g:"C",w:11},{t:"خنثی‌سازی نشتی اسید",x:"خنثی‌سازی مستقیم اسید غلیظ با کربنات یا بی‌کربنات گرما و CO2 زیاد، کف و پاشش تولید می‌کند. ابتدا نشتی را محصور و با پمپ مقاوم جمع کنید، سپس خنثی‌سازی را کنترل‌شده و با اندازه‌گیری pH (حدود ۶ تا ۹) انجام دهید.",r:"CCPS / Prudent Practices (NRC)",d:"HSEW-23",g:"A",w:0},{t:"الکتریسیتهٔ ساکن",x:"اتصال هم‌پتانسیل (bonding) هادی‌ها را هم‌ولتاژ می‌کند و زمین‌کردن آنها را به زمین می‌رساند؛ هیچ‌کدام بار روی مایع یا پلاستیک عایق را تخلیه نمی‌کند. جرقهٔ بدن انسان (چند ده mJ) بسیار بیش از حداقل انرژی اشتعال هیدروژن است.",r:"NFPA 77",d:"HSEW-23",g:"B",w:10},{t:"پیش‌ارزیابی پیمانکار",x:"در پیش‌ارزیابی پیمانکار فقط به TRIR گذشته تکیه نکنید: صفر مورد با ساعت کار کم آماری بی‌ارزش است. سیستم HSE، صلاحیت فنی، آموزش، بیمه و سابقه‌ی کار مشابه (اسید، کار گرم) را ارزیابی کنید. دلیل: عدد گذشته از کیفیت کنترل‌های فعلی خبر نمی‌دهد.",r:"ISO 45001 §8.1.4.2; ANSI/ASSP Z10.0 / HSE UK HSG159",d:"HSEW-28",g:"C",w:14},{t:"بخش‌های SDS",x:"SDS در GHS ۱۶ بخش دارد: بخش ۸ حدود مواجهه و حفاظت فردی، بخش ۹ خواص فیزیکی، بخش ۱۰ پایداری و واکنش‌پذیری (ناسازگاری‌ها)، بخش ۱۱ سم‌شناسی. برای ماتریس ناسازگاری و شرایط اجتنابی، بخش ۱۰ را بخوانید، نه فقط بخش ۷.",r:"GHS Purple Book, Annex 4",g:"A",w:6},{t:"مناطق خطر انفجار",x:"در IEC ۶۰۰۷۹-۱۰-۱ منطقه ۰ یعنی اتمسفر گازی قابل‌انفجار پیوسته یا طولانی، منطقه ۱ محتمل در کار عادی و منطقه ۲ غیرمحتمل و فقط کوتاه‌مدت؛ برای گردوغبار معادل آن ۲۰، ۲۱ و ۲۲ است. طبقه‌بندی بر پایهٔ فراوانی و مدت حضور است نه شدت انفجار.",r:"IEC 60079-10-1/-10-2",d:"HSEW-19",g:"B",w:10},{t:"نیت طراحی در گره",x:"پیش از جلسه‌ی HAZOP، برای هر گره (node) نیت طراحی روشن بنویسید؛ مثلاً انتقال اسید نیتریک از مخزن به اتوکلاو با دبی و دمای مشخص. انحراف یعنی خروج از همین نیت. دلیل: بدون نیت طراحی معلوم نیست «بیشتر» یا «کمتر» نسبت به چه چیزی است.",r:"IEC 61882; CCPS PHA",g:"C",w:11},{t:"فرار حرارتی واکنش",x:"در واکنش گرمازا، نرخ تولید گرما با دما نمایی (آرنیوس) و دفع گرما تقریباً خطی رشد می‌کند، پس بالاتر از دمای بحرانی کنترل از دست می‌رود. اگر واکنش‌دهنده در دمای پایین انباشته شود و واکنش دیر آغاز شود، گرمایش بعدی همه را ناگهان آزاد می‌کند.",r:"Stoessel, Thermal Safety of Chemical Processes / CCPS",d:"HSEW-01",g:"A",w:1},{t:"مجوز در برابر JSA",x:"مجوز کار ابزار کنترل و اجازهٔ زمان‌دار و مکان‌مند است، ولی JSA مراحل کار و خطر هر مرحله را تحلیل می‌کند. مجوزی که بدون JSA اختصاصی همان کار صادر شود فقط یک فرم امضاشده است و کنترل‌های درست را تضمین نمی‌کند.",r:"HSE UK HSG250",d:"HSEW-28",g:"B",w:3},{t:"خطا و تخلف",x:"ریزن: خطا (لغزش، فراموشی، اشتباه) ناخواسته است و با طراحی و رویه‌ی بهتر کم می‌شود؛ تخلف عمدی است (روتین، موقعیتی، استثنایی) و با فهم دلیلش (رویه‌ی غیرعملی، فشار زمان) درمان می‌شود. دلیل: آموزش مجدد برای تخلف روتین اثری ندارد.",r:"Reason 1990; HSE HSG48",g:"C",w:16},{t:"کاتالیست مصرف‌شده",x:"کاتالیست مصرف‌شده ممکن است سولفید، آرسنیک، کک یا روغن باقی‌مانده داشته باشد: انحلال اسیدی سولفید، H2S (و با آرسنیک، آرسین) آزاد می‌کند و مواد آلی با اسید نیتریک واکنش گرمازا دارند. بدون آنالیز و HAZOP، دسته جدید را شارژ نکنید.",r:"IEC 61882 (HAZOP) / CCPS",d:"HSEW-01",g:"A",w:0},{t:"وضعیت ایمن الکتریکی",x:"کار روی تجهیز برقی باید با شرایط کاری الکتریکی ایمن انجام شود: شناسایی همهٔ منابع، قطع، قفل/برچسب، آزمون نبود ولتاژ و در صورت نیاز زمین‌کردن. اتکا به «کلید باز» یا نمودار تک‌خطی بدون آزمون علت رایج برق‌گرفتگی‌های مرگبار است.",r:"NFPA 70E Art. 120",d:"HSEW-20",g:"B",w:10},{t:"نرخ TRIR",x:"TRIR (OSHA) = موارد قابل‌ثبت × ۲۰۰٬۰۰۰ ÷ ساعت کار و علاوه بر روز کاری از دست رفته، محدودیت کار یا انتقال شغل و درمان پزشکی فراتر از کمک‌های اولیه را هم می‌شمارد. دلیل: شمارش فقط LTI، بخش بزرگی از آسیب‌ها را از شاخص حذف می‌کند.",r:"OSHA 29 CFR 1904",g:"C",w:13},{t:"رفتار نشت آمونیاک",x:"آمونیاک گازی (چگالی نسبی حدود ۰٫۶) سبک‌تر از هواست، اما نشت مایع تحت فشار با سرمایش و ایروسل، ابری سنگین نزدیک زمین می‌سازد. IDLH آن ۳۰۰ ppm است؛ محل آشکارساز و مسیر فرار را برای سناریوی نشت مایع هم بسنجید.",r:"NIOSH Pocket Guide (Ammonia)",g:"A",w:2},{t:"محدودیت RCD",x:"RCD با ۳۰ mA حفاظت تکمیلی در برابر جریان نشتی به زمین است؛ اگر کسی همزمان با فاز و نول تماس بگیرد، جریان متعادل است و RCD عمل نمی‌کند. همچنین حفاظت اضافه‌جریان نیست و باید با MCB یا فیوز تکمیل شود.",r:"IEC 60364-4-41",d:"HSEW-21",g:"B",w:10},{t:"علل بلافصل و ریشه‌ای",x:"علت بلافصل آنچه مستقیماً رخ داد است (پاشش اسید از شلنگ)؛ علت ریشه‌ای نقص سیستمی است که اجازه داد (نبود برنامه‌ی بازرسی شلنگ)؛ شرایط پنهان (latent) مدت‌ها قبل کاشته شده. دلیل: اصلاح علت بلافصل یک رویداد را می‌بندد و اصلاح ریشه کل گروه رویدادها را.",r:"CCPS Guidelines for Investigating Process Safety Incidents",g:"C",w:12},{t:"گستره اشتعال هیدروژن",x:"هیدروژن در هوا از حدود ۴٪ تا ۷۵٪ حجمی اشتعال‌پذیر است و انرژی جرقه لازم برای آن بسیار کم است (حدود ۰٫۰۲ میلی‌ژول)، یعنی الکتریسیته ساکن هم کافی است. چون سبک است زیر سقف و نقاط بالای مخزن جمع می‌شود؛ آشکارساز را بالا نصب کنید.",r:"NFPA 2 / CCPS",g:"A",w:1},{t:"پیمانکار در تعمیرات اساسی",x:"در تعمیرات اساسی ورود ناگهانی پیمانکار زیاد، ناآشنایی با مخاطرات سایت و فشار زمان ریسک اصلی است. ISO ۴۵۰۰۱ هماهنگی شناسایی خطرات متقابل با پیمانکار را می‌خواهد؛ القای ویژه، هماهنگ‌کنندهٔ HSE و یک مرجع واحد مجوز ضروری است.",r:"ISO 45001 §8.1.4.2",d:"HSEW-28",g:"B",w:14},{t:"اعتبار پاسخ اپراتور",x:"در LOPA برای پاسخ اپراتور به آلارم معمولاً حداکثر PFD حدود ۰٫۱ اعتبار داده می‌شود، آن هم فقط با آلارم مستقل، زمان کافی، رویه‌ی مکتوب و آموزش. دلیل: زیر استرس و حجم بالای آلارم خطای انسانی زیاد است و ادعای بهتر از آن بدون سند ریسک را کم‌نمایی می‌کند.",r:"CCPS LOPA; IEC 61511",g:"C",w:11},{t:"حساسیت متقاطع حسگرها",x:"حسگر الکتروشیمیایی به گازهای غیرهدف هم پاسخ می‌دهد؛ مثلاً NO2 می‌تواند پاسخ حسگر H2S را کاهش دهد یا منفی کند و خوانش را کمتر از واقعیت نشان دهد. جدول حساسیت متقاطع سازنده را برای مخلوط گازهای هر محل بررسی کنید.",r:"IEC 60079-29-1 / داده سازنده",g:"A",w:2},{t:"سلسله‌مراتب ارتفاع",x:"ابتدا اجتناب از کار در ارتفاع، سپس پیشگیری از سقوط با حفاظ جمعی (نرده، سکو)، بعد توقف سقوط با هارنس و در پایان اقدامات اداری. هارنس خطر را حذف نمی‌کند و فقط پیامد را کم می‌کند، و خودش خطر کشش، برخورد و نجات ایجاد می‌کند.",r:"ANSI/ASSP Z359; ISO 45001 §8.1.2",d:"HSEW-13",g:"B",w:7},{t:"اصلاح و اقدام اصلاحی",x:"اصلاح (correction) نشانه را برطرف می‌کند و اقدام اصلاحی (بند ۱۰.۲) علت ریشه‌ای را حذف می‌کند. کالیبره کردن دتکتور H2S اصلاح است؛ ایجاد زمان‌بندی خودکار کالیبراسیون با مسئول مشخص اقدام اصلاحی است. دلیل: بدون ریشه‌یابی همان عدم‌انطباق برمی‌گردد.",r:"ISO 45001 §10.2",g:"C",w:13},{t:"انفجار ثانویه گرد",x:"اغلب انفجار گرد با رویداد کوچک اولیه آغاز می‌شود که لایه‌های گرد روی تیرها و کانال‌ها را معلق می‌کند و انفجار ثانویه مخرب‌تر می‌شود. لایه‌ای در حد میلی‌متر هم خطرناک است؛ نظافت با باد فشرده ممنوع و جاروبرقی مناسب گرد قابل‌احتراق/HEPA لازم است.",r:"NFPA 652",g:"A",w:4},{t:"اعتبار و آزمون مجدد",x:"مجوز باید محدودیت زمانی (حداکثر یک شیفت) داشته باشد و با تغییر شرایط، توقف طولانی یا بروز بو/آلارم دوباره ارزیابی شود. آزمون گاز اولیه فقط تصویر همان لحظه است؛ جریان‌های فرآیندی و واکنش‌ها ساعتی بعد اتمسفر را عوض می‌کنند.",r:"HSE UK HSG250; OSHA 1910.146",g:"B",w:3},{t:"فرهنگ گزارش شبه‌حادثه",x:"تعداد زیاد گزارش شبه‌حادثه نشانه‌ی فرهنگ سالم است، نه سیستم ناایمن؛ افت ناگهانی گزارش‌ها معمولاً یعنی ترس یا بی‌اعتمادی. دلیل: بازخورد سریع به گزارش‌دهنده و اجرای اقدام، انگیزه‌ی گزارش بعدی است.",r:"CCPS RBPS; ISO 45001 §10.2",g:"C",w:12},{t:"فولاد کربنی و اسید رقیق",x:"اسید سولفوریک غلیظ (بالای حدود ۷۰٪ و در دمای محیط) روی فولاد کربنی لایه محافظ سولفات آهن می‌سازد، اما با رقیق‌شدن این لایه از بین می‌رود و خوردگی سریع همراه با تولید هیدروژن رخ می‌دهد. نفوذ آب به مخزن اسید غلیظ یعنی خطر خوردگی و گاز اشتعال‌پذیر.",r:"NACE / راهنمای مواد ساخت اسید سولفوریک",d:"HSEW-23",g:"A",w:0},{t:"فضای مجوزدار",x:"فضا مجوزدار است اگر خطر اتمسفری بالقوه، امکان غرق‌شدگی، دیوارهٔ همگرا یا خطر جدی دیگر داشته باشد. مخزن اسیدی و هاپر کیک نیکل دست‌کم به‌دلیل اتمسفر یا غرق‌شدگی مجوزدارند؛ تنزل فقط وقتی ممکن است که تهویه به‌تنهایی خطر اتمسفری را کنترل کند و مستند شود.",r:"OSHA 1910.146(b),(c)(5)",d:"HSEW-01",g:"B",w:5},{t:"مدیریت تغییر موقت",x:"تغییر موقت (جامپر روی تریپ، بای‌پس دتکتور) هم مشمول مدیریت تغییر بند ۸.۱.۳ است و باید ارزیابی ریسک، تأیید، اقدام جبرانی و تاریخ انقضا داشته باشد. دلیل: «موقت»ها بدون ردگیری دائمی می‌شوند و یک لایه‌ی حفاظتی را بی‌صدا حذف می‌کنند.",r:"ISO 45001 §8.1.3; CCPS RBPS (MOC)",g:"C",w:14},{t:"محدودیت قانون هابر",x:"قانون هابر (غلظت×زمان ثابت) فقط برای برخی سموم تجمعی تقریبی است؛ برای محرک‌ها (NO2، آمونیاک، مه اسید) و H2S اثر به غلظت لحظه‌ای وابسته است. میانگین‌گیری TWA نباید پیک کوتاه را پنهان کند؛ از حد سقف/STEL و پایش لحظه‌ای استفاده کنید.",r:"ACGIH TLV Introduction / AIHA",g:"A",w:9},{t:"بلایند در برابر شیر",x:"بلایند (اسپید یا اسپکتکل) برخلاف شیر نشتی سیت ندارد، اما باید با فشار و جنس مناسب انتخاب، شماره‌دار و در فهرست ایزولاسیون ثبت شود. بلایند فراموش‌شده هنگام راه‌اندازی خطر مستقیم است، پس برداشتن آن باید در چک‌لیست بستن مجوز و راه‌اندازی بیاید.",r:"HSE UK HSG253",d:"HSEW-22",g:"B",w:3},{t:"ریسک باقیمانده",x:"ریسک باقیمانده فقط وقتی معتبر است که کنترل‌ها واقعاً کار کنند. اگر شیر اطمینان، دتکتور یا اینترلاک معیوب یا بای‌پس باشد، ریسک واقعی به ریسک پیش از کنترل نزدیک می‌شود. دلیل: ثبت ریسک باید به وضعیت آزمون و بازرسی کنترل‌های بحرانی گره بخورد.",r:"ISO 45001 §6.1.2; CCPS RBPS",g:"C",w:11},{t:"جاذب نشتی نیتریک",x:"برای نشتی اسید نیتریک هرگز جاذب آلی (خاک‌اره، پارچه، کاغذ) به کار نبرید: اکسایش گرمازا باعث دود قهوه‌ای NOx و آتش می‌شود. از جاذب معدنی مناسب (ماسه خشک، ورمیکولیت) یا جاذب ویژه اسید و ظرف مقاوم استفاده کنید.",r:"SDS / NFPA 400",d:"HSEW-23",g:"A",w:0},{t:"ترتیب آزمون اتمسفر",x:"ترتیب استاندارد آزمون: اکسیژن، سپس گازهای قابل‌اشتعال، سپس سمی‌ها. حسگر LEL کاتالیستی برای سوختن به اکسیژن کافی نیاز دارد و کمبود یا غنی‌بودن O2 دقتش را مختل می‌کند؛ نمونه‌برداری باید در چند ارتفاع انجام شود.",r:"OSHA 1910.146",g:"B",w:5},{t:"نمودار ایشیکاوا",x:"نمودار ایشیکاوا علل بالقوه را در دسته‌هایی مثل انسان، ماشین، روش، مواد، اندازه‌گیری و محیط (۶M) فهرست می‌کند. این ابزار فقط طوفان فکری است و هر شاخه باید با شواهد تأیید یا رد شود. دلیل: بدون راستی‌آزمایی، فهرست علل به حدس تبدیل می‌شود.",r:"ISO 31010; CCPS Incident Investigation",g:"C",w:12},{t:"APF و حداکثر غلظت",x:"حداکثر غلظت قابل استفاده = APF × حد مواجهه. در OSHA 1910.134 نیم‌ماسک ۱۰، تمام‌صورت ۵۰ و SCBA فشار-مثبت ۱۰٬۰۰۰ است. اگر غلظت نیکل ۳۰ برابر حد باشد، نیم‌ماسک کافی نیست و دست‌کم تمام‌صورت لازم است.",r:"OSHA 1910.134 Table 1",g:"A",w:6},{t:"نسبت ۴:۱ نردبان",x:"پای نردبان باید یک‌چهارم ارتفاع تکیه‌گاه از دیوار فاصله داشته باشد (۴:۱ ≈ ۷۶ درجه) و حدود ۱ m (۳ فوت) بالاتر از سکو امتداد یابد. زاویهٔ مسطح‌تر باعث لغزش پایه و خمش نردبان و زاویهٔ تندتر باعث واژگونی به عقب می‌شود.",r:"OSHA 1926.1053(b)",d:"HSEW-18",g:"B",w:7},{t:"نمونه‌گیری در ممیزی",x:"ممیز با نمونه‌گیری ریسک‌محور شواهد عینی را از مدرک، مصاحبه و مشاهده جمع می‌کند؛ یک نمونه‌ی ناقص تا بررسی دامنه‌ی مشکل «درصد» نیست. اگر در ۱۰ مجوز یک ایراد دیده شد، نمونه را گسترش دهید. دلیل: باید معلوم شود مورد اتفاقی است یا سیستمی.",r:"ISO 19011",g:"C",w:13},{t:"باز کردن اتوکلاو",x:"اتوکلاو پس از واکنش ممکن است فشار باقی‌مانده، گاز محبوس (H2، CO2، NOx) و محتوای داغ‌تر از نقطه جوش اتمسفری داشته باشد. باز کردن درب بدون تأیید فشار و دمای ایمن، قفل‌ها و ایزولاسیون مثبت، می‌تواند درب را پرتاب و اسید داغ را بپاشد.",r:"ASME BPVC VIII-1 / CCPS",d:"HSEW-22",g:"A",w:0},{t:"سقوط آزاد و نیرو",x:"OSHA حداکثر سقوط آزاد ۱٫۸ m (۶ فوت) و نیروی ایست حداکثر ۸ kN (۱۸۰۰ lbf) با هارنس تمام‌بدن را اجازه می‌دهد. اتصال زیر سطح پا سقوط آزاد و نیرو را بالا می‌برد و جاذب انرژی را شاید حتی کامل باز نکند؛ نقطهٔ اتصال ایده‌آل بالای سر است.",r:"OSHA 1926.502(d)(16)",d:"HSEW-13",g:"B",w:7},{t:"اثربخشی اقدام اصلاحی",x:"بستن عدم‌انطباق با «اقدام انجام شد» کافی نیست؛ بند ۱۰.۲ بازنگری اثربخشی را می‌خواهد. چند ماه بعد نمونه‌ای از رکوردها یا مشاهده‌ی میدانی را بررسی کنید تا معلوم شود علت واقعاً رفع شده است. دلیل: اجرای اقدام با کاهش ریسک یکی نیست.",r:"ISO 45001 §10.2",g:"C",w:13},{t:"نفوذ، تراوش و تخریب",x:"Penetration عبور مایع از منفذ یا درز است؛ Permeation عبور مولکولی بدون سوراخ (breakthrough time) است؛ Degradation تغییر فیزیکی دستکش (سفت‌شدن، تورم) است. دستکشی با breakthrough طولانی هم می‌تواند سریع تخریب شود؛ مثلاً نیتریل با اسید نیتریک غلیظ. جدول سازنده را برای غلظت و دما ببینید.",r:"EN ISO 374-1 / ASTM F739",g:"A",w:6},{t:"کارهای همزمان SIMOPS",x:"خطر اصلی کارهای همزمان، تداخل مجوزهاست؛ مثلاً جوشکاری نزدیک فلنجی که برای تعمیر باز می‌شود. صادرکننده باید همهٔ مجوزهای فعال را روی یک تابلو یا ماتریس مرکزی ببیند؛ بی‌خبری هر تیم از مجوز تیم دیگر در Piper Alpha نقش اصلی داشت.",r:"HSE UK HSG250; Cullen Report",d:"HSEW-22",g:"B",w:14},{t:"مدل پنیر سوئیسی",x:"در مدل ریزن حادثه وقتی رخ می‌دهد که سوراخ‌های لایه‌های دفاعی هم‌راستا شوند؛ سوراخ‌ها شامل خطاهای فعالِ لحظه‌ای و شرایط پنهان ناشی از تصمیم‌های مدیریتی‌اند. دلیل: تحقیق باید بالادست را هم بگردد، نه فقط آخرین لایه (اپراتور).",r:"Reason 1997",g:"C",w:12},{t:"Bump test و کالیبراسیون",x:"Bump test با گاز فقط پاسخ و آلارم را تأیید می‌کند؛ کالیبراسیون دقت عدد را تنظیم می‌کند. ISEA توصیه می‌کند پیش از هر روز استفاده، آشکارساز پرتابل bump test شود؛ شکست تست یعنی کالیبراسیون و در صورت تکرار شکست، خروج از سرویس.",r:"ISEA Statement on Validation of Portable Gas Monitors",g:"A",w:2},{t:"شعاع و مدت مراقبت جوش",x:"NFPA 51B شعاع ۳۵ فوت (≈۱۱ m) را برای پاک‌سازی یا پوشش مواد سوختنی در نظر می‌گیرد، چون جرقه و ذرات مذاب تا این فاصله و از شکاف‌ها به طبقات پایین می‌روند. دیده‌بان آتش باید حین کار و پس از آن (طبق OSHA حداقل ۳۰ دقیقه) باقی بماند.",r:"NFPA 51B; OSHA 1910.252",d:"HSEW-14",g:"B",w:1},{t:"کالیبراسیون ماتریس",x:"ماتریس ریسک را کالیبره کنید: بازه‌های احتمال با فراوانی کمّی (مثلاً یک بار در ۱۰ سال)، شدت‌ها با پیامد مشخص برای انسان، محیط و دارایی و آستانه‌ها هم‌سو با تحمل ریسک مدیریت. دلیل: واژه‌ی «محتمل» برای هر ارزیاب معنای متفاوتی دارد و نتایج قابل‌مقایسه نمی‌شود.",r:"ISO 31000; CCPS RBPS",g:"C",w:11},{t:"فعال‌سازی هفتگی چشم‌شو",x:"واحد لوله‌کشی‌شده را هفتگی فعال و کل ایستگاه را سالانه بازرسی کنید؛ آب راکد رسوب، زنگ و میکروب دارد و می‌تواند خود به چشم آسیب بزند. ثبت بازرسی و علامت‌گذاری واضح جزو الزامات است.",r:"ANSI/ISEA Z358.1",g:"A",w:15},{t:"استحکام نقطهٔ اتصال",x:"نقطهٔ اتصال توقف سقوط باید برای هر نفر ۵۰۰۰ lbf (≈۲۲٫۲ kN) تحمل کند یا زیر نظر شخص صلاحیت‌دار با ضریب ایمنی ۲ طراحی شود. دو نفر روی یک نقطه یعنی حدود ۴۴ kN؛ لوله و نرده فرآیندی معمولاً چنین استحکامی ندارند.",r:"OSHA 1926.502(d)(15)",d:"HSEW-13",g:"B",w:7},{t:"شدت و میانگین شدت",x:"نرخ شدت = روزهای کاری از دست رفته × ۱٬۰۰۰٬۰۰۰ ÷ ساعت کار (یا مبنای ۲۰۰٬۰۰۰)، و میانگین شدت = روزهای از دست رفته ÷ تعداد LTI. دلیل: دو کارخانه با LTIFR یکسان می‌توانند شدت بسیار متفاوت داشته باشند و تفاوت فقط در شاخص شدت دیده می‌شود.",r:"ANSI Z16.1; ILO",g:"C",w:13}],qs:[{id:"e001",t:"رقیق‌سازی اسید",q:"برای ساخت ۱۰۰۰ کیلوگرم محلول ۳۰٪ وزنی از اسید سولفوریک ۹۸٪ وزنی، چند کیلوگرم آب لازم است و ترتیب افزودن چگونه باشد؟",o:["حدود ۶۹۴ کیلوگرم آب؛ آب به‌تدریج روی اسید ریخته شود","حدود ۳۰۶ کیلوگرم آب؛ اسید به‌تدریج به آب افزوده شود","حدود ۶۹۴ کیلوگرم آب؛ اسید به‌تدریج به آبِ همزده‌شده با پایش دما","حدود ۴۲۰ کیلوگرم آب؛ هر دو هم‌زمان وارد مخزن شوند"],a:2,e:"جرم اسید خالص = ۳۰۰ کیلوگرم، پس اسید ۹۸٪ حدود ۳۰۶ کیلوگرم و آب حدود ۶۹۴ کیلوگرم است. ریختن آب روی اسید غلیظ موجب جوشش و پاشش موضعی می‌شود.",r:"CCPS / SDS اسید سولفوریک",d:"HSEW-01",g:"A",w:0},{id:"e002",t:"هیدروژن و کار گرم",q:"پیش از کار گرم روی مخزن اسید تخلیه‌شده، آشکارساز (کالیبره با هیدروژن) ۵۰٪ LEL را نشان می‌دهد. غلظت حجمی تقریبی هیدروژن و تصمیم درست کدام است؟",o:["حدود ۲٪ حجمی؛ کار مجاز است چون از ۴٪ کمتر است","حدود ۵۰٪ حجمی؛ فقط تخلیه ساختمان لازم است","حدود ۰٫۵٪ حجمی؛ با تهویه کار گرم مجاز است","حدود ۲٪ حجمی؛ کار گرم ممنوع، تهویه و یافتن منشأ هیدروژن"],a:3,e:"LEL هیدروژن ۴٪ است و ۵۰٪ آن برابر ۲٪ حجمی می‌شود. ۵۰٪ LEL به‌هیچ‌وجه برای کار گرم قابل قبول نیست؛ مقدار کمتر از LEL به معنای ایمن بودن نیست.",r:"NFPA 51B / IEC 60079-29-1",d:"HSEW-14",g:"A",w:1},{id:"e003",t:"Bump test",q:"آشکارساز چندگازه پرتابل پیش از شیفت در bump test با گاز H2S به آلارم نمی‌رود، اما صفحه نمایش عدد نشان می‌دهد. اقدام درست کدام است؟",o:["استفاده با افزودن ذهنی ۲۰٪ به خوانش برای جبران","کاهش نقطه آلارم دستگاه تا در تست به صدا درآید","ادامه کار چون باتری سالم است و عدد نمایش داده می‌شود","خروج از سرویس، کالیبراسیون و تکرار bump؛ در صورت شکست، تعویض حسگر"],a:3,e:"Bump test که آلارم نمی‌دهد یعنی دستگاه قابل اتکا نیست؛ باید کالیبره و دوباره آزمون شود و در صورت شکست از رده خارج گردد. دستکاری آلارم یا تصحیح ذهنی بی‌پایه است.",r:"ISEA Statement on Validation of Portable Gas Monitors",g:"A",w:2},{id:"e004",t:"مسمومیت حسگر",q:"پس از تعمیرات با اسپری روان‌کار سیلیکونی در اتاق پمپ، آشکارساز ثابت LEL صفر نشان می‌دهد، اما در تست با گاز فقط حدود ۴۰٪ مقدار انتظار را می‌دهد. محتمل‌ترین علت و اقدام چیست؟",o:["مسمومیت حسگر کاتالیستی با سیلیکون؛ کالیبراسیون با گاز و در صورت ناتوانی در تنظیم، تعویض حسگر","دریفت صفر عادی که با تنظیم صفر برطرف می‌شود","نبود گاز در اتاق؛ پاسخ ضعیف طبیعی است","رطوبت بالا؛ پس از خشک‌شدن حسگر خودبه‌خود اصلاح می‌شود"],a:0,e:"سیلیکون از سموم شناخته‌شده حسگر کاتالیستی است و حساسیت را کم می‌کند؛ تنظیم صفر اثری ندارد. دستگاه باید از سرویس خارج، کالیبره و اگر نرسید تعویض شود.",r:"IEC 60079-29-1 / داده سازنده",g:"A",w:2},{id:"e005",t:"LEL آمونیاک",q:"در واحد بازیابی آمونیاک، آشکارساز LEL صفر نشان می‌دهد، اما کارکنان تحریک چشم و بوی تند گزارش می‌کنند. تفسیر درست کدام است؟",o:["نشان‌دهنده نبود آمونیاک است؛ بوی تند ناشی از اسید است","حساسیت حسگر کم است؛ کافی است آلارم را از ۲۰٪ به ۱۰٪ LEL ببریم","LEL آمونیاک حدود ۱۵٪ حجمی است؛ غلظت سمی روی LEL دیده نمی‌شود و حسگر سمی لازم است","خوانش LEL باید در ۱۵ ضرب شود تا ppm سمی به دست آید"],a:2,e:"۱٪ LEL آمونیاک حدود ۱۵۰۰ ppm است و ۳۰۰ ppm (IDLH) به‌سختی روی LEL دیده می‌شود. تغییر نقطه آلارم یا ضریب‌دهی ذهنی این ضعف ذاتی را برطرف نمی‌کند.",r:"NIOSH Pocket Guide / IEC 60079-29-1",d:"HSEW-03",g:"A",w:2},{id:"e006",t:"نجات H2S",q:"کارگری در گودال کنار مخزن انحلال بیهوش افتاده و آشکارساز ثابت ۲۰۰ ppm H2S نشان می‌دهد. همکاران می‌خواهند با ماسک کارتریج‌دار فوراً وارد شوند. اولین اقدام درست؟",o:["ورود دونفره با ماسک تمام‌صورت کارتریج‌دار، چون هر دقیقه حیاتی است","جلوگیری از ورود، اعلام اضطرار و نجات با تیم دارای SCBA و سیستم بازیابی","ورود یک نفر با حبس نفس برای بیرون کشیدن سریع","ریختن آب روی گودال برای جذب H2S و سپس ورود"],a:1,e:"در این غلظت ماسک تصفیه‌کننده مجاز و مؤثر نیست و ورود بدون SCBA قربانی دوم می‌سازد. نجات باید با تجهیزات هوای رسان و بازیابی انجام شود.",r:"OSHA 1910.146 / 1910.134",g:"A",w:2},{id:"e007",t:"خستگی بویایی",q:"اپراتور می‌گوید: «چند دقیقه پیش بوی H2S می‌آمد، حالا نمی‌آید؛ پس غلظت کم شده و می‌توان ماسک را برداشت.» ارزیابی درست؟",o:["درست است، چون آستانه بوی H2S بسیار پایین‌تر از حد مجاز است","درست است، اگر بیش از ۱۵ دقیقه از بوییدن گذشته باشد","قابل اتکا نیست؛ خستگی یا فلج بویایی رخ می‌دهد و تصمیم فقط با آشکارساز معتبر","نادرست فقط بالاتر از ۱۰۰۰ ppm؛ زیر آن بو معیار قابل قبولی است"],a:2,e:"H2S حس بویایی را در غلظت‌های بالا (از حدود ۱۰۰ ppm) فلج می‌کند، پس نبود بو دلیل کاهش غلظت نیست. معیار تصمیم باید ابزار اندازه‌گیری باشد.",r:"NIOSH Pocket Guide (H2S)",g:"A",w:2},{id:"e008",t:"کاتالیست حاوی سولفید",q:"قرار است نخستین بار دسته‌ای کاتالیست مصرف‌شده با سولفید باقی‌مانده به راکتور اسید سولفوریک شارژ شود. کدام اقدام پیش از شروع اولویت بیشتری دارد؟",o:["افزایش دمای اولیه تا انحلال سریع‌تر و زمان شارژ کمتر شود","شارژ یک‌جا تا مدت باز بودن درب کوتاه‌تر شود","آنالیز سولفید/آرسنیک، شارژ تدریجی و تخلیه گاز به اسکرابر با آشکارساز H2S","تکیه صرف بر ماسک کارتریج‌دار برای اپراتور"],a:2,e:"انحلال اسیدی سولفید H2S ناگهانی تولید می‌کند؛ کنترل با شناخت ترکیب، نرخ شارژ و مهار/اسکرابر انجام می‌شود. گرمایش یا شارژ یک‌جا نرخ تولید گاز را بالا می‌برد و ماسک کارتریج‌دار برای H2S راه‌حل نیست.",r:"CCPS / IEC 61882",d:"HSEW-01",g:"A",w:0},{id:"e009",t:"نشتی نیتریک و جاذب آلی",q:"پس از نشتی ۵۰ لیتر اسید نیتریک ۶۵٪ کنار پالت‌ها، کارگر برای جمع‌آوری از خاک‌اره استفاده کرد. ده دقیقه بعد خاک‌اره دود قهوه‌ای می‌دهد و داغ می‌شود. اولین اقدام؟",o:["تخلیه افراد با رعایت جهت باد، اعلام اضطرار؛ ورود مجدد فقط با SCBA","افزودن خاک‌اره خشک بیشتر برای جذب گرما","جمع‌آوری سریع خاک‌اره با دست‌کش و حمل به بیرون","خاموش‌کردن آن با ابتدا ماسک ساده و سپس پودر خشک"],a:0,e:"خاک‌اره ماده آلی است و با اسید نیتریک اکسایش گرمازا می‌دهد و NOx سمی و آتش ایجاد می‌کند. اولویت، جان افراد (تخلیه و اضطرار) است، نه رفع کار با ابزار دستی.",r:"NFPA 400 / SDS",d:"HSEW-23",g:"A",w:1},{id:"e010",t:"NO2 و اثر تأخیری",q:"کارگری هنگام شارژ فلز در اسید نیتریک چند دقیقه ابر قهوه‌ای استنشاق کرده، سرفه خفیف دارد و می‌خواهد کار را ادامه دهد. تصمیم درست؟",o:["ادامه کار و ارجاع فقط در صورت بروز تنگی نفس","استراحت ۳۰ دقیقه و بازگشت پس از قطع سرفه","ارجاع پزشکی و مراقبت چند ساعته تا ۲۴ ساعت یا بیشتر به‌دلیل ادم ریوی تأخیری","تنفس هوای تازه و اگر ۱۰ دقیقه بعد سرفه نبود، بازگشت"],a:2,e:"NO2 اغلب ادم ریوی با تأخیر چند ساعته ایجاد می‌کند؛ نبود علامت شدید در ابتدا مطمئن‌کننده نیست و مراقبت پزشکی لازم است.",r:"NIOSH / ACGIH (NO2)",d:"HSEW-01",g:"A",w:1},{id:"e011",t:"حد تعدیل‌شده شیفت",q:"حد مواجهه ۸ ساعته یک گرد برابر ۰٫۱ mg/m³ است. اگر شیفت ۱۲ ساعته باشد، حد تعدیل‌شده طبق مدل Brief & Scala چقدر است؟",o:["۰٫۰۶۷ mg/m³","۰٫۰۵ mg/m³","۰٫۰۷۵ mg/m³","۰٫۱۰۰ mg/m³ (بدون تغییر)"],a:1,e:"ضریب = (۸/۱۲)×((۲۴−۱۲)/۱۶) = ۰٫۵ پس حد ۰٫۰۵ می‌شود. تنها تناسب ساده ۸/۱۲ (۰٫۰۶۷) زمان ریکاوری کمتر را لحاظ نمی‌کند.",r:"Brief & Scala (1975) / ACGIH",g:"A",w:9},{id:"e012",t:"محاسبه TWA",q:"نمونه‌برداری شخصی: ۲ ساعت با ۰٫۴۰، ۴ ساعت با ۰٫۰۴ و ۲ ساعت با ۰٫۰۲ mg/m³ (جمعاً ۸ ساعت). حد TWA برابر ۰٫۱ mg/m³ است. نتیجه؟",o:["TWA برابر ۰٫۱۵۳ (میانگین ساده سه عدد) است؛ بالاتر از حد","TWA برابر ۰٫۰۸۰ است؛ مجاز","TWA برابر ۰٫۰۶۵ است؛ مجاز","TWA برابر ۰٫۱۲۵ است؛ بالاتر از حد"],a:3,e:"TWA = (۲×۰٫۴۰ + ۴×۰٫۰۴ + ۲×۰٫۰۲)/۸ = ۰٫۱۲۵. میانگین ساده بدون وزن‌دهی زمانی نادرست است.",r:"ACGIH / OSHA",g:"A",w:9},{id:"e013",t:"اثر ترکیبی",q:"هوای یک سالن: مه اسید سولفوریک ۰٫۱۲ mg/m³ (TLV برابر ۰٫۲) و بخار اسید نیتریک ۱ ppm (TLV-TWA برابر ۲). هر دو محرک دستگاه تنفس‌اند. ارزیابی؟",o:["شاخص ترکیبی ۰٫۶ است؛ هر کدام زیر حد خودش است","شاخص ترکیبی ۱٫۱ است؛ از حد بیشتر است","میانگین دو نسبت (۰٫۵۵) ملاک است؛ مجاز","شاخص ۱٫۱ است ولی چون ماده‌ها متفاوت‌اند مجاز است"],a:1,e:"برای مواد با اثر مشابه، مجموع Ci/Li نباید از ۱ بیشتر شود: ۰٫۶ + ۰٫۵ = ۱٫۱. سنجش جداگانه هر ماده اثر افزایشی را نادیده می‌گیرد.",r:"ACGIH TLV (Mixtures)",d:"HSEW-01",g:"A",w:9},{id:"e014",t:"حد انحراف",q:"ماده‌ای TLV-TWA برابر ۲ mg/m³ دارد و STEL ندارد. در یک کار کوتاه ۱۰ دقیقه‌ای غلظت ۱۲ mg/m³ اندازه‌گیری شد و TWA روزانه زیر ۲ است. ارزیابی؟",o:["غیرقابل قبول؛ بیش از ۵ برابر TLV است و در هیچ مدتی مجاز نیست","قابل قبول؛ چون TWA رعایت شده است","قابل قبول؛ چون کمتر از ۱۵ دقیقه است","قابل قبول؛ تا ۶ برابر TLV در کمتر از ۳۰ دقیقه مجاز است"],a:0,e:"طبق قاعده انحراف ACGIH، نوسان بیش از ۳ برابر فقط تا مجموع ۳۰ دقیقه مجاز است و هرگز بیش از ۵ برابر نباید رخ دهد؛ ۱۲ از ۱۰ (۵ برابر) بیشتر است.",r:"ACGIH TLV (Excursion Limits)",g:"A",w:9},{id:"e015",t:"حد سقف در برابر TWA",q:"یک ماده محرک دارای حد سقف ۵ ppm است. میانگین ۸ ساعته ۱ ppm، اما ۱۰ دقیقه حین تخلیه ۲۰ ppm ثبت شده است. نتیجه؟",o:["مجاز؛ چون TWA کمتر از ۵ ppm است","نقض؛ حد سقف هرگز نباید رد شود و TWA پایین آن را جبران نمی‌کند","مجاز؛ چون ۱۰ دقیقه کمتر از دوره STEL است","نقض فقط اگر پیک بیش از ۳۰ دقیقه طول بکشد"],a:1,e:"حد سقف در هیچ لحظه‌ای نباید رد شود؛ میانگین‌گیری TWA برای ماده‌ای با اثر حاد معیار مناسب نیست.",r:"ACGIH TLV Introduction",g:"A",w:9},{id:"e016",t:"چشم‌شوی خودایستا",q:"برای ایستگاه تخلیه اسید سولفوریک یک چشم‌شوی خودایستای ۲۰ لیتری با دبی ۱٫۵ لیتر/دقیقه نصب شده است. ارزیابی طبق ANSI Z358.1؟",o:["ناکافی؛ ۲۰ لیتر فقط حدود ۱۳ دقیقه شست‌وشو می‌دهد و ۱۵ دقیقه لازم است","کافی؛ ۱۰ دقیقه شست‌وشو برای اسید قابل قبول است","ناکافی؛ چون خودایستا هرگز نمی‌تواند چشم‌شوی اصلی باشد","کافی؛ اگر نزدیک‌تر از ۱۰ ثانیه راه باشد"],a:0,e:"الزام ۱۵ دقیقه با ۱٫۵ لیتر/دقیقه یعنی حدود ۲۲٫۵ لیتر؛ ۲۰ لیتر فقط ۱۳٫۳ دقیقه می‌دهد. واحد خودایستا اگر ظرفیت کافی داشته باشد مجاز است.",r:"ANSI/ISEA Z358.1",d:"HSEW-23",g:"A",w:15},{id:"e017",t:"ادامه شست‌وشوی چشم",q:"فردی با پاشش اسید سولفوریک به چشم ۱۵ دقیقه شست‌وشو کرده و درد او تمام شده است. اقدام بعدی؟",o:["پایان درمان و بازگشت به کار چون درد برطرف شده","چکاندن محلول بی‌کربنات رقیق برای خنثی‌سازی اسید باقی‌مانده","استراحت یک ساعته و ارجاع فقط در صورت قرمزی","ادامه شست‌وشو در مسیر و ارجاع به چشم‌پزشک؛ قطع درد دلیل سلامت نیست"],a:3,e:"آسیب قرنیه با اسید غلیظ ممکن است درد را کم کند؛ باید شست‌وشو ادامه یابد و ارزیابی تخصصی شود. خنثی‌سازی شیمیایی داخل چشم مجاز نیست.",r:"ANSI/ISEA Z358.1 / SDS",d:"HSEW-27",g:"A",w:15},{id:"e018",t:"نشتی اسید غلیظ",q:"۵۰۰ لیتر اسید سولفوریک ۹۸٪ در حوضچه مهار (bund) ریخته است. رویکرد مناسب جمع‌آوری؟",o:["جمع‌آوری با پمپ یا مکنده مقاوم به ظرف مناسب و خنثی‌سازی کنترل‌شده باقی‌مانده","غرقاب فوری با آب فراوان برای رقیق‌سازی","پاشیدن مستقیم پودر سودا اش روی کل استخر اسید","پوشاندن با خاک‌اره و جاروکردن"],a:0,e:"آب فراوان روی اسید غلیظ گرمای شدید و پاشش ایجاد می‌کند؛ کربنات مستقیم کف و گرما دارد و جاذب آلی ممکن است گرم شود. انتقال و سپس خنثی‌سازی کنترل‌شده امن‌تر است.",r:"CCPS / SDS",d:"HSEW-23",g:"A",w:0},{id:"e019",t:"انباشت فشار هنگام تخلیه",q:"MAWP یک اتوکلاو ۱۰ bar است و یک شیر اطمینان دارد (بدون حریق). در یک رویداد، اوج فشار ۱۱٫۳ bar ثبت شد. ارزیابی؟",o:["قابل قبول؛ چون کمتر از فشار هیدروتست (۱۳ bar) است","قابل قبول؛ چون شیر باز شده و عمل کرده است","از ۱۱ bar (۱۰٪ انباشت مجاز) بیشتر است؛ ظرفیت و نصب شیر باید بازبینی شود","قابل قبول؛ تا ۲۰٪ بالاتر از MAWP مجاز است"],a:2,e:"برای یک شیر در حالت غیرحریق، انباشت حداکثر ۱۰٪ است. فشار هیدروتست معیار مجاز بودن رویداد نیست و باز شدن شیر به‌تنهایی کفایت آن را نشان نمی‌دهد.",r:"ASME BPVC VIII-1",g:"A",w:0},{id:"e020",t:"دیسک انفجاری زیر شیر",q:"در سرویس اسید، یک دیسک انفجاری زیر شیر اطمینان نصب شده و گیج فضای بین آن‌ها است. چرا این گیج و دریچه تخلیه مهم است؟",o:["فشار محبوس فشار ترکیدن دیسک را پایین می‌آورد و فقط باعث باز شدن زودهنگام می‌شود","فشار محبوس ناشی از نشتی دیسک به فشار ترکیدن اضافه می‌شود و حفاظت را مختل می‌کند","گیج برای کنترل فرایند و تنظیم شیر کاربرد دارد","فقط برای کالیبراسیون سالانه شیر لازم است"],a:1,e:"فشار بین دیسک و شیر در جهت مقابل بازشدن دیسک عمل می‌کند و برای دیسک متداول فشار ترکیدن مؤثر را بالا می‌برد؛ گیج و دریچه نشتی را آشکار و فشار را تخلیه می‌کنند.",r:"ASME BPVC VIII-1 / API 520",g:"A",w:0},{id:"e021",t:"انباشت واکنش‌دهنده",q:"در انحلال کلوخه نیکل کربنات، اپراتور اسید را در دمای پایین اضافه کرد، واکنش دیده نشد و سپس برای شروع شدن واکنش گرم کرد. خطر اصلی؟",o:["کاهش بازده انحلال که فقط به کیفیت محصول لطمه می‌زند","خوردگی بیشتر تجهیز به‌دلیل دمای پایین","رسوب بلورین که فقط فیلتر را مسدود می‌کند","انباشت واکنش‌دهنده و شروع ناگهانی و شدید با گاز و کف فراوان"],a:3,e:"اگر ماده در دمای پایین بدون واکنش انباشته شود، با شروع واکنش گرمای انباشته و گاز (CO2) به‌ناگهان آزاد می‌شود. تغذیه باید تابع آغاز واکنش و کنترل‌شده باشد.",r:"CCPS / Stoessel",d:"HSEW-01",g:"A",w:1},{id:"e022",t:"خرابی خنک‌کننده",q:"در اتوکلاو اسید با واکنش گرمازا و افزودن نیم‌پیوسته، با خرابی آب خنک‌کننده دما از مقدار تنظیم‌شده بالا می‌رود. اولین اقدام؟",o:["فقط افزایش دبی خنک‌کننده و ادامه تغذیه","قطع تغذیه واکنش‌دهنده، ادامه همزن و فعال‌سازی خنک‌کننده یا مهار اضطراری","توقف همزن تا گرمای اصطکاکی کم شود","تخلیه دستی فوری به جو"],a:1,e:"سوخت واکنش یعنی ماده در حال تغذیه؛ قطع آن اولین قدم است و همزن برای انتقال حرارت و جلوگیری از نقاط داغ لازم است. تخلیه دستی به جو خطرناک است.",r:"CCPS / Stoessel",d:"HSEW-01",g:"A",w:0},{id:"e023",t:"بازرسی مخزن فشار",q:"ضخامت اندازه‌گیری‌شده ۱۲٫۰ میلی‌متر، ضخامت حداقل مورد نیاز ۸٫۰ میلی‌متر و نرخ خوردگی ۰٫۵ میلی‌متر در سال است. حداکثر فاصله بازرسی داخلی طبق API 510 چقدر است؟",o:["۸ سال","۱۰ سال","۴ سال","۲ سال"],a:2,e:"عمر باقی‌مانده = (۱۲−۸)/۰٫۵ = ۸ سال؛ فاصله بازرسی حداکثر نصف آن یا ۱۰ سال (کمتر) است، پس ۴ سال.",r:"API 510",d:"HSEW-22",g:"A",w:0},{id:"e024",t:"گونه‌های نیکل",q:"ارزیاب ریسک می‌خواهد برای گرد نیکل کربنات از حد مواجهه نیکل فلزی استفاده کند. ایراد اصلی؟",o:["ترکیبات نیکل با فلز از نظر انحلال و سرطان‌زایی فرق دارند و حد جداگانه دارند","هیچ ایرادی نیست؛ همه نیکل‌ها حد یکسان دارند","فقط تفاوت رنگ ماده است","حد نیکل فلزی همیشه سخت‌گیرانه‌تر از ترکیبات است"],a:0,e:"IARC ترکیبات را گروه ۱ و فلز را ۲B می‌داند و ACGIH برای عنصری، محلول و نامحلول TLV جداگانه دارد.",r:"IARC 100C / ACGIH TLV",g:"A",w:4},{id:"e025",t:"نمونه‌گیری ادرار نیکل",q:"نمونه ادرار نیکل کارگر دوشنبه صبح (پیش از شروع کار پس از تعطیلی آخر هفته) پایین بود و مدیر نتیجه گرفت مواجهه پایین است. ارزیابی؟",o:["معتبر؛ نیکل در بدن سال‌ها می‌ماند","نامعتبر؛ نیمه‌عمر کوتاه است و نمونه باید پایان شیفت/هفته باشد و گرد نامحلول را نشان نمی‌دهد","معتبر؛ نمونه صبح همیشه بهترین نمونه است","نامعتبر فقط چون یک نمونه کافی نیست"],a:1,e:"نیکل محلول نیمه‌عمر ساعت‌ها تا یکی دو روز دارد، پس پس از تعطیلی افت می‌کند؛ ضمن آنکه جذب اکسید نامحلول را خوب نشان نمی‌دهد.",r:"اصول پایش زیستی / ATSDR Nickel",g:"A",w:9},{id:"e026",t:"نظافت گرد نیکل",q:"در سالن پودر نیکل، برای کاهش مواجهه و خطر انفجار، کدام روش نظافت مناسب‌تر است؟",o:["دمیدن با باد فشرده با فشار کم","جاروی خشک نرم و بسته‌بندی گرد","جاروبرقی مجهز به فیلتر HEPA و مناسب گرد قابل‌احتراق","بالا بردن دور فن تا گرد به مکش برود"],a:2,e:"باد فشرده، جارو و فن گرد را معلق می‌کنند (مواجهه و ابر انفجاری). جاروبرقی HEPA مناسب مناطق گرد قابل‌احتراق گرد را جمع می‌کند بی‌آنکه پخش شود.",r:"NFPA 652",g:"A",w:4},{id:"e027",t:"محاسبه Kst",q:"در کره ۲۰ لیتری، بیشینه نرخ افزایش فشار یک گرد ۳۰۰ bar/s اندازه‌گیری شد. Kst و کلاس آن چیست؟ (V^(1/3) برای ۰٫۰۲ m³ حدود ۰٫۲۷ است)",o:["حدود ۳۰۰ bar·m/s؛ St3","حدود ۳۰۰ bar·m/s؛ St2","حدود ۴۲ bar·m/s؛ St1","حدود ۸۱ bar·m/s؛ St1"],a:3,e:"Kst = (dP/dt)max × V^(1/3) = ۳۰۰ × ۰٫۲۷۱ ≈ ۸۱ و کمتر از ۲۰۰ یعنی St1. عدد dP/dt خام را نباید Kst گرفت و ضرب در √V نادرست است.",r:"EN 14034 / NFPA 68",g:"A",w:4},{id:"e028",t:"گرد کوره احیا",q:"برگه ایمنی اکسید نیکل «غیرقابل‌احتراق» ذکر کرده است. آیا می‌توان گرد جمع‌شده از کوره احیا را بدون آزمون همین‌طور دانست؟",o:["بله؛ چون ترکیب نیکل است و همه نیکل‌ها قابل‌احتراق نیستند","خیر؛ ممکن است نیکل فلزی احیا‌شده داشته باشد و باید روی نمونه واقعی آزمون Kst/MIE شود","بله؛ چون کوره‌ها گرد را اکسید می‌کنند","خیر؛ فقط به‌دلیل رنگ خاکستری آن"],a:1,e:"اکسید کامل ممکن است قابل‌احتراق نباشد، اما گرد کوره احیا ممکن است فلز ریزدانه داشته باشد؛ ارزیابی باید روی نمونه واقعی انجام شود.",r:"NFPA 652",g:"A",w:4},{id:"e029",t:"انفجار ثانویه",q:"پس از فلش‌فایر کوچک در یک فیلتر کیسه‌ای، لایه ضخیم گرد روی تیرهای سقف دیده می‌شود. چرا این لایه‌ها نگران‌کننده‌اند؟",o:["چون رسانا هستند و برق می‌گیرند","انفجار اولیه آن‌ها را معلق می‌کند و انفجار ثانویه بزرگ‌تری ایجاد می‌شود","فقط ظاهر نامناسب دارند و بهداشت را کم می‌کنند","چون وزنشان سازه را ضعیف می‌کند"],a:1,e:"انفجار اولیه لایه‌ها را معلق و ابر بزرگ‌تری می‌سازد؛ انفجار ثانویه معمولاً بسیار مخرب‌تر است.",r:"NFPA 652",g:"A",w:4},{id:"e030",t:"بخش‌های SDS",q:"برای یک ماده جدید می‌خواهید حد مواجهه، دستکش مناسب و داده سمیت حاد (LD50) را پیدا کنید. به ترتیب کدام بخش‌های SDS؟",o:["بخش ۷، بخش ۸، بخش ۱۲","بخش ۱۱، بخش ۸، بخش ۹","بخش ۷، بخش ۷، بخش ۱۱","بخش ۸، بخش ۸، بخش ۱۱"],a:3,e:"بخش ۸ حدود مواجهه و حفاظت فردی (از جمله دست) و بخش ۱۱ اطلاعات سم‌شناسی است؛ بخش ۷ جابه‌جایی و نگهداری و بخش ۱۲ اطلاعات زیست‌محیطی است.",r:"GHS Purple Book, Annex 4",g:"A",w:6},{id:"e031",t:"انتخاب ماسک",q:"غلظت گرد نیکل هیدروکسید ۳٫۰ mg/m³ و حد ۰٫۱ mg/m³ است. کدام انتخاب مناسب است؟",o:["تمام‌صورت با فیلتر P100 (APF برابر ۵۰) با آزمون تناسب موفق","نیم‌ماسک با فیلتر P100 (APF برابر ۱۰)","PAPR با هود شل (APF برابر ۲۵)","نیم‌ماسک فیلتردار N95 (APF برابر ۱۰)"],a:0,e:"نسبت خطر ۳٫۰/۰٫۱ = ۳۰ است؛ APF باید دست‌کم ۳۰ باشد. فقط تمام‌صورت (۵۰) کافی است و نیم‌ماسک (۱۰) و هود شل (۲۵) کفایت ندارند.",r:"OSHA 1910.134 Table 1",g:"A",w:6},{id:"e032",t:"آمونیاک و IDLH",q:"در نشتی آمونیاک خوانش ۵۰۰ ppm است. تیم برای بستن شیر می‌خواهد با ماسک تمام‌صورت با کارتریج آمونیاک (APF برابر ۵۰) وارد شود. تصمیم؟",o:["مجاز است؛ ۵۰×۲۵ بیشتر از ۵۰۰ ppm است","مجاز است اگر زمان کار کمتر از ۱۰ دقیقه باشد","مجاز نیست؛ بالاتر از IDLH (۳۰۰ ppm) فقط SCBA فشار-مثبت مجاز است","مجاز است اگر کارتریج جدید باشد"],a:2,e:"ماسک تصفیه‌کننده در جو IDLH مجاز نیست؛ حاصل‌ضرب APF در حد مواجهه معیار کافی نیست و باید SCBA فشار-مثبت (یا معادل) استفاده شود.",r:"OSHA 1910.134(d) / NIOSH",d:"HSEW-27",g:"A",w:6},{id:"e033",t:"ریش و گرد نیکل",q:"کارگری به‌دلیل پوست یا اعتقادات نمی‌تواند ریش را کوتاه کند و نیکل ۱ mg/m³ (حد ۰٫۱) است. گزینه مناسب؟",o:["نیم‌ماسک با بندهای محکم‌تر","نیم‌ماسک N95 با تست کیفی ساخارین","PAPR با کلاه یا هود شل که به آب‌بند صورت وابسته نیست و APF مناسب دارد","تمام‌صورت با seal check دقیق"],a:2,e:"ریش بین لبه آب‌بند و پوست آب‌بندی را از بین می‌برد؛ seal check یا تست کیفی ساخارین جایگزین نیست. هود شل به آب‌بندی صورت وابسته نیست (نسبت خطر ۱۰ و APF برابر ۲۵).",r:"OSHA 1910.134(g)",g:"A",w:6},{id:"e034",t:"تخریب دستکش",q:"جدول سازنده برای دستکش نیتریل در تماس با اسید نیتریک غلیظ breakthrough بالا نشان می‌دهد، ولی پس از یک ساعت کار سطح دستکش سفت و ترک‌دار شده است. این پدیده چیست؟",o:["نفوذ (penetration) از منفذ ریز؛ فقط باید دستکش ضخیم‌تر شود","تراوش (permeation) که طبیعی است و ربطی به ماده ندارد","سالم بودن دستکش؛ سفتی فقط ناشی از عرق است","تخریب (degradation) دستکش؛ باید جنس مقاوم‌تر یا ارزیابی تخریب انتخاب شود"],a:3,e:"تخریب تغییر خواص فیزیکی دستکش بر اثر ماده است و جدا از breakthrough بررسی می‌شود؛ اسید نیتریک غلیظ اکسنده است و برخی دستکش‌ها را سریع تخریب می‌کند.",r:"EN ISO 374-1/-5 / داده سازنده",d:"HSEW-23",g:"A",w:6},{id:"e035",t:"بازرسی هفتگی چشم‌شو",q:"در ممیزی مشاهده می‌کنید چشم‌شوی لوله‌کشی‌شده ماهی یک‌بار فعال می‌شود و ثبت دارد. ارزیابی طبق ANSI Z358.1؟",o:["عدم انطباق؛ فعال‌سازی هفتگی لازم است","انطباق؛ ماهانه کافی است اگر ثبت شود","انطباق؛ فقط بازرسی سالانه الزامی است","عدم انطباق؛ فعال‌سازی باید روزانه باشد"],a:0,e:"ANSI Z358.1 فعال‌سازی هفتگی واحد لوله‌کشی‌شده و بازرسی سالانه را می‌خواهد؛ هدف حذف رسوب، زنگ و آلودگی میکروبی است.",r:"ANSI/ISEA Z358.1",d:"HSEW-23",g:"A",w:15},{id:"e036",t:"گازسنجی عمقی",q:"پیش از ورود به مخزن شست‌وشو‌شده با اسید، گازسنجی فقط از دریچه بالا انجام شد: اکسیژن ۲۰٫۹٪، LEL صفر، H2S صفر. اقدام درست؟",o:["نمونه‌برداری در چند عمق و نقطه، چون گازها طبقه‌بندی می‌شوند؛ سپس تصمیم ورود","ورود مجاز است چون هر سه پارامتر خوب است","فقط ۱۰ دقیقه بیشتر تهویه کنیم و بدون آزمون دوباره وارد شویم","ورود مجاز با ماسک کارتریج‌دار"],a:0,e:"H2 سبک و H2S سنگین در سطوح مختلف جمع می‌شوند؛ نمونه سطحی نماینده کل فضا نیست. ماسک کارتریج‌دار جای آزمون صحیح را نمی‌گیرد.",r:"OSHA 1910.146 / NIOSH",g:"A",w:5},{id:"e037",t:"سرعت جذب LEV",q:"سرعت جذب هود دهانه ساده در فاصله ۰٫۳ متر برابر ۰٫۵ m/s است. اگر منبع به ۰٫۶ متر برود، سرعت جذب تقریبی چقدر می‌شود؟",o:["حدود ۰٫۲۵ m/s","حدود ۰٫۰۶۲ m/s","حدود ۰٫۵ m/s (تقریباً بدون تغییر)","حدود ۰٫۱۲۵ m/s"],a:3,e:"در هود دهانه ساده سرعت تقریباً با عکس مجذور فاصله افت می‌کند؛ دو برابر فاصله یعنی یک‌چهارم: ۰٫۵/۴ = ۰٫۱۲۵.",r:"ACGIH Industrial Ventilation Manual",g:"A",w:9},{id:"e038",t:"تهویه رقیق‌کننده",q:"پیشنهاد شده برای کنترل گرد نیکل در سالن، به‌جای هود گیرنده، فن‌های دیواری عمومی نصب شود. ایراد اصلی؟",o:["فن‌های دیواری فقط صدا دارند","غلظت منطقه تنفس نزدیک منبع را کم نمی‌کند و برای ماده سرطان‌زا با منبع متمرکز مناسب نیست","تهویه عمومی همیشه غیرقانونی است","فقط برای سالن‌های بالای ده متر ارتفاع کار می‌کند"],a:1,e:"تهویه رقیق‌کننده فقط غلظت متوسط را کاهش می‌دهد و ممکن است گرد را به مناطق دیگر پخش کند؛ گرفتن در منبع برای مواد سمی/سرطان‌زا ترجیح دارد.",r:"ACGIH IVM / ISO 45001 §8.1.2",g:"A",w:9},{id:"e039",t:"سلسله‌مراتب کنترل",q:"کدام اقدام برای کاهش مواجهه با گرد نیکل در سلسله‌مراتب کنترل بالاتر است؟",o:["نصب هود موضعی روی نقطه تخلیه","چرخش کارگران بین ایستگاه‌ها","تأمین ماسک P100 برای همه","تبدیل گرد خشک به خمیر/دوغاب و انتقال بسته"],a:3,e:"حذف یا جایگزینی (تغییر شکل ماده برای نبود گرد) بالاتر از کنترل مهندسی، اداری و PPE است.",r:"ISO 45001 §8.1.2",g:"A",w:9},{id:"e040",t:"صدک ۹۵ مواجهه",q:"در یک SEG میانگین حسابی مواجهه ۰٫۰۶ mg/m³ و GSD برابر ۳ است؛ حد ۰٫۱ mg/m³. ارزیابی؟",o:["غیرقابل قبول؛ صدک ۹۵ حدود ۰٫۲ است و از حد بیشتر است","قابل قبول؛ میانگین کمتر از حد است","قابل قبول؛ GSD اهمیتی ندارد","غیرقابل قبول؛ چون میانگین باید کمتر از ۰٫۰۱ باشد"],a:0,e:"با توزیع لگ‌نرمال، صدک ۹۵ حدود ۰٫۲ mg/m³ می‌شود (دو برابر حد)؛ تصمیم بر پایه صدک ۹۵ است، نه میانگین.",r:"AIHA Strategy",g:"A",w:9},{id:"e041",t:"زاویهٔ بند",q:"بار ۳ تنی با بند دوشاخه بالا می‌رود و زاویهٔ هر شاخه با افق ۳۰° است. کشش هر شاخه تقریباً چند کیلوگرم نیرو است؟",o:["حدود ۱۵۰۰ kgf","حدود ۱۷۳۲ kgf","حدود ۳۰۰۰ kgf","حدود ۲۶۰۰ kgf"],a:2,e:"T = W/(۲·sin30°) = ۳۰۰۰/(۲×۰٫۵) = ۳۰۰۰ kgf؛ یعنی هر شاخه کل بار را تحمل می‌کند. عدد ۱۵۰۰ مربوط به شاخه‌های عمودی و ۱۷۳۲ مربوط به زاویهٔ ۶۰° است.",r:"ASME B30.9",d:"HSEW-17",g:"B",w:8},{id:"e042",t:"فضای آزاد سقوط",q:"کارگری با بند ۱٫۸ m و جاذب انرژی (کشش حداکثر ۱٫۰۷ m) به نقطه‌ای هم‌سطح پای خود متصل است. جابه‌جایی حلقهٔ D ≈۰٫۳ m، حلقه تا پا ≈۱٫۵ m، حاشیه ۰٫۹ m و کف زیرین ۵ m پایین‌تر است. ارزیابی؟",o:["کافی نیست؛ نیاز ≈۵٫۶ m است و باید اتصال بالاسری یا خط‌حیات جمع‌شونده به کار رود","کافی است؛ ۱٫۸ + ۱٫۰۷ = ۲٫۸۷ m از ۵ m کمتر است","کافی است؛ جاذب انرژی سقوط آزاد را حذف می‌کند","کافی نیست، اما افزودن بند دوم موازی مشکل را حل می‌کند"],a:0,e:"۱٫۸+۱٫۰۷+۰٫۳+۱٫۵+۰٫۹ ≈ ۵٫۶ m بزرگ‌تر از ۵ m است. محاسبهٔ ناقص که فقط سقوط آزاد و کشش جاذب را جمع می‌کند، حلقهٔ D، قد و حاشیهٔ ایمنی را نادیده می‌گیرد.",r:"OSHA 1926.502(d)(16); ANSI Z359.13",d:"HSEW-13",g:"B",w:7},{id:"e043",t:"شاخص بلندکردن",q:"کارگر بار ۲۰ kg را از روی پالت بلند می‌کند و بار ۵۰ cm از بدن فاصلهٔ افقی دارد؛ بقیهٔ ضرایب معادلهٔ NIOSH برابر ۱ است. شاخص بلندکردن (LI) تقریباً چند است؟",o:["حدود ۰٫۸۷","حدود ۳٫۵","حدود ۱٫۰","حدود ۱٫۷"],a:3,e:"HM = ۲۵/۵۰ = ۰٫۵ پس RWL = ۲۳×۰٫۵ = ۱۱٫۵ kg و LI = ۲۰/۱۱٫۵ ≈ ۱٫۷. عدد ۰٫۸۷ با فرض RWL=۲۳ kg و نادیده‌گرفتن فاصلهٔ افقی به دست می‌آید.",r:"NIOSH Lifting Equation 94-110",d:"HSEW-24",g:"B",w:8},{id:"e044",t:"زمان مجاز نویز",q:"مواجههٔ یکنواخت ۹۴ dBA است. طبق معیار NIOSH (REL برابر ۸۵ dBA و نرخ تبادل ۳ dB) مدت مجاز روزانه چقدر است؟",o:["۴٫۶ ساعت","۱ ساعت","۲ ساعت","۳۰ دقیقه"],a:1,e:"T = ۸/۲^((۹۴−۸۵)/۳) = ۸/۲³ = ۱ ساعت. مقدار ۴٫۶ ساعت از معیار OSHA (نرخ ۵ dB و آستانهٔ ۹۰) به دست می‌آید که معیار این پرسش نیست.",r:"NIOSH 98-126; OSHA 1910.95",g:"B",w:8},{id:"e045",t:"دور مجاز دیسک",q:"دیسک ساب ۱۸۰ mm با حداکثر سرعت محیطی ۸۰ m/s روی سنگ‌ساب ۹۰۰۰ دور بر دقیقه سوار شده است. نتیجه؟",o:["حد دور دیسک ≈۱۷۰۰۰ rpm است؛ استفاده مجاز است","حد دور دیسک ≈۸۵۰۰ rpm است؛ این ماشین بالاتر است و نباید استفاده شود","حد دور ≈۸۵۰۰ rpm است ولی ۶٪ اختلاف قابل‌تحمل است","حد دور مطرح نیست؛ فقط قطر فلنج مهم است"],a:1,e:"n = ۸۰×۶۰/(π×۰٫۱۸) ≈ ۸۴۹۰ rpm. دور ماشین بیشتر است و مجاز نیست؛ تحمل‌پذیری برای دور بیش از رتبه وجود ندارد و رقم ۱۷۰۰۰ از جایگزینی شعاع به جای قطر می‌آید.",r:"EN 12413",d:"HSEW-25",g:"B",w:8},{id:"e046",t:"نگهبان فضای بسته",q:"حین کار در مخزن خنثی‌سازی، نگهبان بیرونی می‌بیند ورودی ناگهان افتاد و پاسخ نمی‌دهد. اولین اقدام درست نگهبان؟",o:["ورود سریع با دستگاه تنفس مستقل چون هر ثانیه حیاتی است","ورود پس از ۵ دقیقه تهویهٔ شدید با فن","ترک پست برای آوردن نفر دوم و ورود دونفره","اعلام اضطرار و فراخوان تیم نجات، همزمان بازیابی با طناب بدون ورود"],a:3,e:"نگهبان نباید وارد شود؛ ورود نجات‌گر بدون تیم و تجهیز علت بخش بزرگی از تلفات است. بازیابی غیرورودی و فراخوان نجات سریع‌ترین و کم‌خطرترین مسیر است.",r:"OSHA 1910.146(i); NIOSH 86-110",d:"HSEW-27",g:"B",w:5},{id:"e047",t:"CO2 پنهان",q:"پس از خنثی‌سازی کیک کربنات نیکل با اسید، O2 مخزن ۱۹٫۹٪ و LEL صفر است. تفسیر درست؟",o:["O2 در حد مجاز است ولی CO2 حدود ۵٪ هم با این عدد سازگار است؛ CO2 را مستقیم اندازه بگیرید و تهویه کنید","ورود مجاز است چون O2 بالاتر از ۱۹٫۵٪ است","افت ۱٪ اکسیژن ناچیز و احتمالاً خطای حسگر است","ورود با ماسک فیلتر‌دار مجاز است چون O2 کافی است"],a:0,e:"O2 از ۲۰٫۹ به ۱۹٫۹ یعنی حدود ۴٫۸٪ جایگزینی با گاز دیگر که می‌تواند CO2 نزدیک IDLH (۴٪) باشد. ماسک فیلتر‌دار CO2 را جذب نمی‌کند و عبور O2 از حد پایین تنها معیار ایمنی نیست.",r:"OSHA 1910.146; NIOSH IDLH",d:"HSEW-01",g:"B",w:5},{id:"e048",t:"دیده‌بان آتش",q:"حین جوشکاری روی سکوی طبقهٔ دوم تالار، دیده‌بان آتش هم‌سطح جوشکار ایستاده است. زیر سکو بشکه‌های مواد قابل‌اشتعال و شکاف کف وجود دارد. نقص اصلی؟",o:["دیده‌بان باید کپسول CO2 به جای پودری داشته باشد","مشکلی نیست چون شعاع ۱۱ m فقط روی همان طبقه سنجیده می‌شود","مسیر سقوط جرقه به طبقهٔ پایین پوشش داده نشده؛ باید مواد حذف/پوشانده یا ناظر گذاشته شود","بشکه‌های طبقهٔ دیگر مشمول مجوز جوش نیستند"],a:2,e:"جرقه و ذرات مذاب از شکاف‌ها به سطوح پایین می‌روند و شعاع ۱۱ m سه‌بعدی ارزیابی می‌شود. دیده‌بان باید همهٔ نقاط قابل‌دسترسی برای جرقه را ببیند یا آنها را ایمن کرد.",r:"NFPA 51B",d:"HSEW-14",g:"B",w:1},{id:"e049",t:"جوش و هیدروژن",q:"مخزن فولاد کربنی که دو هفته پیش اسید سولفوریک رقیق داشته تخلیه و شسته شده است. تعمیرکار می‌خواهد فقط از بیرون جوش دهد. تصمیم؟",o:["چون شسته شده است آزمون لازم نیست","پوشاندن اطراف با پتوی نسوز کافی است","جوش بیرونی حرارت درون را منتقل نمی‌کند، پس اشتعال ممکن نیست","پیش از جوش، فضای مخزن برای هیدروژن/LEL آزمون و تهویه یا بی‌اثر شود"],a:3,e:"فلز داغ و رسوب باقی‌مانده می‌توانند هیدروژن تولید و در سقف مخزن جمع کنند و جرقه یا گرمای جوش بیرونی آن را مشتعل کند. پتوی نسوز اطراف گاز داخل را کنترل نمی‌کند.",r:"NFPA 51B",d:"HSEW-14",g:"B",w:1},{id:"e050",t:"بلید مداوم",q:"برای تعمیر پمپ خط اسید دو شیر بسته و شیر بلید میانی باز است. با وجود گذشت زمان کافی برای تخلیه، از بلید قطرات مداوم می‌چکد. تفسیر درست؟",o:["قطرات عادی است و کار ادامه یابد چون هر دو شیر بسته‌اند","شیر بالادست نشت دارد؛ ایزولاسیون اثبات نشده و باید بلایند یا تعمیر شیر انجام شود","بلید را ببندید تا نشت قطع شود و کار ادامه یابد","فقط تخلیهٔ باقی‌ماندهٔ خط است و اهمیتی ندارد"],a:1,e:"چکیدن مداوم پس از زمان کافی تخلیه یعنی شیر نشتی دارد؛ بستن بلید فقط علامت را پنهان و فشار پشت فلنج را برقرار می‌کند. هدف بلید دقیقاً آشکارسازی همین نشتی است.",r:"HSE UK HSG253",d:"HSEW-22",g:"B",w:3},{id:"e051",t:"برداشتن قفل غایب",q:"کارگر روز، قفل خود را روی همزن اتوکلاو گذاشته و به خانه رفته است و شیفت شب باید تجهیز را راه‌اندازی کند. اقدام درست؟",o:["طبق رویهٔ مستند و با تأیید مدیریت: اطمینان از نبود فرد در سایت، تلاش برای تماس و اطلاع او پیش از بازگشت به کار","کلید یدک را به سرپرست شیفت بدهند تا قفل را بردارد","قفل باز شود چون با پایان شیفت مجوز خودبه‌خود باطل شده است","قفل برداشته نشود و کار تا بازگشت او متوقف بماند"],a:0,e:"OSHA برای قفل فرد غایب رویهٔ خاص مدیریتی می‌خواهد و اجازهٔ برداشتن ساده ندارد. گزینهٔ توقف تا بازگشت فرد ممکن است ایمن باشد ولی رویهٔ الزامی را حل نمی‌کند.",r:"OSHA 1910.147(e)(3)",d:"HSEW-22",g:"B",w:3},{id:"e052",t:"مهار انرژی",q:"قبل از تعمیر گیربکس همزن روی سکوی بازویی که با سیلندر هیدرولیک بالا نگه داشته شده، برق و پمپ هیدرولیک قفل شده‌اند. اقدام مکمل ضروری؟",o:["قفل برق کافی است چون منبع انرژی قطع شده","کاهش فشار هیدرولیک تا ۵۰٪ و ادامه","مهار مکانیکی بار با تکیه‌گاه و تخلیهٔ فشار هیدرولیک، سپس آزمون","اعلام به همکاران برای دوری از زیر سکو"],a:2,e:"گرانش و روغن محبوس انرژی ذخیره‌شده‌اند و با قفل برق از بین نمی‌روند؛ نشت یا باز شدن شیر می‌تواند بار را رها کند. باید مهار مکانیکی و تخلیه شود.",r:"OSHA 1910.147(d)(5)",d:"HSEW-22",g:"B",w:3},{id:"e053",t:"ایزولاسیون اتوکلاو",q:"برای ورود به اتوکلاو متصل به هدر آمونیاک، کدام ایزولاسیون قابل‌اعتمادتر است؟",o:["دو شیر بسته با قفل و برچسب","جداسازی فیزیکی یا بلایند فلنجی روی خط","شیر کنترل در حالت fail-closed","بستن شیر و ثبت وضعیت آن در DCS"],a:1,e:"بلایند یا قطع فیزیکی وابسته به نشتی سیت و خطای عملگر یا کنترل نیست. شیر قفل‌شده یا حالت fail-closed می‌تواند نشت کند و DCS فقط موقعیت اعلامی را نشان می‌دهد.",r:"HSE UK HSG253; OSHA 1910.146",d:"HSEW-01",g:"B",w:3},{id:"e054",t:"تداخل مجوزها",q:"مجوز الف: بازکردن فلنج خط اسید نیتریک در تالار. مجوز ب: برش با سنگ‌ساب ۸ m دورتر در همان تالار. هر دو جداگانه تأیید شده‌اند. نقص؟",o:["۸ m بیش از حد مجاز ۶ m است و مشکلی نیست","افزودن دیده‌بان آتش مشکل را حل می‌کند","فقط مجوز الف باید ماسک تنفسی را الزام کند","تداخل مجوزها بررسی نشده؛ ارزیابی کارهای همزمان و تعلیق یا جابه‌جایی یکی لازم است"],a:3,e:"خطر از ترکیب دو کار ناشی می‌شود، نه هر مجوز تنها؛ اسید نیتریک با مواد آلی و فلزات واکنش می‌دهد و جرقهٔ برش می‌تواند آن را به آتش تبدیل کند. صادرکننده باید تداخل را قبل از تأیید ببیند.",r:"HSE UK HSG250",d:"HSEW-28",g:"B",w:3},{id:"e055",t:"مجوز دست‌به‌دست",q:"صبح، سرپرست جدید مجوز ورود به مخزن را که دیشب امضا شده و آزمون گاز آن ۱۰ ساعت پیش است می‌بیند و کار ادامه دارد. اقدام درست؟",o:["ادامهٔ کار چون مجوز هنوز در بازهٔ ۲۴ ساعت است","فقط امضای سرپرست جدید روی مجوز کافی است","بازدید مشترک، بازبینی ایزولاسیون، آزمون مجدد اتمسفر و امضای دوباره قبل از ادامه","ادامهٔ کار با پایش پیوسته و بدون آزمون جدید"],a:2,e:"مجوز با تغییر مسئول خودبه‌خود معتبر نمی‌ماند و آزمون قدیمی شرایط فعلی را نشان نمی‌دهد. پایش پیوسته جایگزین بازبینی ایزولاسیون و تأیید گیرندهٔ جدید نیست.",r:"HSE UK HSG250; OSHA 1910.146",d:"HSEW-28",g:"B",w:3},{id:"e056",t:"ممیزی ایزولاسیون",q:"ممیزی نشان می‌دهد صادرکننده فرم ایزولاسیون را پیش از اجرای فیزیکی امضا می‌کند و پیمانکار خودش قفل می‌زند. کدام اصلاح اولویت دارد؟",o:["تأیید میدانی ایزولاسیون پیش از صدور و ثبت شمارهٔ قفل/برچسب","آموزش مجدد پیمانکار دربارهٔ تکمیل فرم","افزودن امضای مدیر دوم روی فرم","کاهش مدت اعتبار مجوز به ۴ ساعت"],a:0,e:"ضعف، نبود راستی‌آزمایی مستقل در محل است؛ افزودن امضا یا آموزش کاغذی آن را رفع نمی‌کند. فرم باید بازتاب وضعیت واقعی باشد نه جایگزین آن.",r:"HSE UK HSG250; OSHA 1910.147",d:"HSEW-28",g:"B",w:3},{id:"e057",t:"ظرفیت خالص جرثقیل",q:"طبق جدول سازنده (ظرفیت ناخالص) در شعاع ۱۲ m ظرفیت ۵٫۰ t است. بار ۴٫۴ t، بلوک قلاب ۰٫۴ t و بندها ۰٫۳ t هستند. تصمیم؟",o:["مجاز نیست؛ مجموع ۵٫۱ t است و باید شعاع کم یا جرثقیل بزرگ‌تر انتخاب شود","مجاز است؛ ۴٫۴ t حدود ۸۸٪ ظرفیت است","مجاز است؛ ضریب ایمنی جرثقیل تا ۶ t را پوشش می‌دهد","مجاز است اگر سرعت بلندکردن کم شود"],a:0,e:"وزن بلوک قلاب و بندها جزو بار کل بر ظرفیت جدول‌اند: ۴٫۴+۰٫۴+۰٫۳ = ۵٫۱ t > ۵٫۰. ضریب ایمنی سازنده برای عملکرد بیش از جدول استفاده نمی‌شود و سرعت کم خطر اضافه‌بار را رفع نمی‌کند.",r:"ASME B30.5",d:"HSEW-17",g:"B",w:8},{id:"e058",t:"جنس بند",q:"در تالار انحلال اسیدی که پاشش اسید ضعیف ممکن است، کدام بند نواری منطقی‌تر است؟",o:["نایلون، چون در برابر اسید مقاوم‌تر است","هر دو بی‌اثرند و فرقی ندارند","پلی‌استر، چون نایلون در برابر اسید تخریب می‌شود","پلی‌استر، چون نایلون فقط در برابر قلیا آسیب می‌بیند"],a:2,e:"نایلون از اسید آسیب می‌بیند و پلی‌استر در برابر اسیدهای معمول مقاوم‌تر است. گزینهٔ آخر دلیل را برعکس بیان می‌کند: نایلون به قلیا مقاوم و به اسید حساس است.",r:"ASME B30.9",d:"HSEW-17",g:"B",w:0},{id:"e059",t:"ظرفیت لیفتراک",q:"لیفتراک ۲۰۰۰ kg در مرکز بار ۵۰۰ mm باید باری ۱۸۰۰ kg با مرکز ثقل ۷۰۰ mm از پشت فورک‌ها ببرد. ارزیابی؟",o:["مجاز است چون ۱۸۰۰ کمتر از ۲۰۰۰ است","مجاز است اگر دکل کاملاً به عقب متمایل شود","مجاز است اگر فقط ۱ m بالا برود","ظرفیت در ۷۰۰ mm حدود ۱۴۳۰ kg است؛ حمل ۱۸۰۰ kg مجاز نیست"],a:3,e:"ظرفیت تقریباً با لنگر ثابت تغییر می‌کند: ۲۰۰۰×۵۰۰/۷۰۰ ≈ ۱۴۳۰ kg. تمایل دکل و ارتفاع کم جبران لنگر اضافه را نمی‌کنند و باید پلاک سازنده ملاک باشد.",r:"OSHA 1910.178(o); ANSI/ITSDF B56.1",d:"HSEW-26",g:"B",w:8},{id:"e060",t:"لیفتراک در رمپ",q:"لیفتراک با بشکهٔ سنگین باید از رمپ شیب‌دار پایین برود. روش درست؟",o:["رو به جلو با سرعت کم و فشار روی ترمز","بار رو به بالای شیب؛ یعنی دنده‌عقب حرکت با بار","فورک‌ها را بالا ببرد تا بار از رمپ دور باشد","رو به جلو با فورک کاملاً بالا برای دید بهتر"],a:1,e:"در شیب با بار، بار باید به سمت بالای شیب باشد تا مرکز ثقل داخل مثلث بماند؛ فورک بالا مرکز ثقل را بالا می‌برد و واژگونی را آسان می‌کند.",r:"OSHA 1910.178(n)(7); ANSI/ITSDF B56.1",d:"HSEW-26",g:"B",w:8},{id:"e061",t:"آشکارساز هیدروژن",q:"در اتاق شارژ باتری سرب‌اسید می‌خواهید آشکارساز هیدروژن نصب کنید. بهترین جا؟",o:["نزدیک کف اتاق","ارتفاع ۱٫۵ m مانند ناحیهٔ تنفس","کنار شارژر در ۰٫۵ m کف","نزدیک سقف و بالای محل شارژ"],a:3,e:"هیدروژن با چگالی بخار حدود ۰٫۰۷ بسیار سبک است و زیر سقف جمع می‌شود. نصب در کف یا ارتفاع تنفس، نشت سقفی را دیر می‌بیند.",r:"OSHA 1910.178(g); NIOSH Pocket Guide",d:"HSEW-26",g:"B",w:1},{id:"e062",t:"مرز قوس برق",q:"در مطالعهٔ قوس برق طبق NFPA 70E، مرز قوس برق (Arc Flash Boundary) بر چه پایه‌ای تعریف می‌شود؟",o:["فاصله‌ای که انرژی به ۸ cal/cm² می‌رسد","فاصله‌ای که انرژی تابشی به ۱٫۲ cal/cm² می‌رسد","فاصله‌ای که انرژی ۴۰ cal/cm² است","فاصلهٔ ثابت ۱ m برای همهٔ ولتاژها"],a:1,e:"مرز قوس برق فاصله‌ای است که انرژی تابشی ۱٫۲ cal/cm² می‌شود، آستانهٔ سوختگی درجه دو. ۴۰ cal/cm² عدد حد بالایی بسیار خطرناک است و فاصله ثابت نیست.",r:"NFPA 70E §130.5",d:"HSEW-19",g:"B",w:10},{id:"e063",t:"RCD و تماس دوفاز",q:"کارگر هنگام تعمیر سنگ‌ساب روشن، با یک دست فاز و با دست دیگر نول تماس می‌گیرد و RCD ۳۰ mA عمل نمی‌کند. دلیل؟",o:["جریان از فاز به نول از بدن می‌گذرد و عدم تعادل جریان به زمین ندارد","RCD حتماً معیوب است","۳۰ mA برای جریان از دست به دست خیلی کم است","RCD فقط برای جریان مستقیم DC طراحی می‌شود"],a:0,e:"RCD اختلاف جریان رفت و برگشت را می‌سنجد؛ مسیر فاز-بدن-نول متعادل است و آن را نمی‌بیند. بنابراین RCD حفاظت تکمیلی است و جایگزین ایزولاسیون نمی‌شود.",r:"IEC 60364-4-41",d:"HSEW-21",g:"B",w:10},{id:"e064",t:"جعبه IP67",q:"تأمین‌کننده برای سالن شست‌وشو با جت پرفشار جعبه‌تقسیم IP67 پیشنهاد می‌دهد. ارزیابی؟",o:["IP67 بالاتر از IP65 است، پس جت را هم پوشش می‌دهد","IP فقط گردوغبار را می‌سنجد و به آب ربطی ندارد","IP67 جت قوی را پوشش نمی‌دهد؛ تأیید IPX6 یا IPX9 جداگانه لازم است","IP67 برای محیط اسیدی ایده‌آل است"],a:2,e:"سطوح IPX سلسله‌مراتبی نیستند و IPX7 (غوطه‌وری) شامل IPX5 و IPX6 (جت) نیست. IP هم دربارهٔ خوردگی نمی‌گوید.",r:"IEC 60529",d:"HSEW-19",g:"B",w:10},{id:"e065",t:"منطقه ۲",q:"نقطه‌ای که اتمسفر گازی قابل‌انفجار در کار عادی غیرمحتمل است و در صورت وقوع فقط کوتاه‌مدت می‌ماند، طبق IEC ۶۰۰۷۹-۱۰-۱ کدام منطقه است؟",o:["منطقه ۱","منطقه ۰","منطقه ۲","منطقه ۲۱"],a:2,e:"منطقه ۲ برای حضور غیرمحتمل و کوتاه است، منطقه ۱ برای حضور گاه‌به‌گاه در کار عادی و منطقه ۰ پیوسته یا طولانی. منطقه ۲۱ برای گردوغبار قابل‌انفجار است.",r:"IEC 60079-10-1",d:"HSEW-19",g:"B",w:10},{id:"e066",t:"درایو خاموش",q:"پمپ تغذیهٔ اسید با VFD قفل‌گذاری شده و نمایشگر درایو خاموش است. تعمیرکار می‌خواهد درب درایو را باز کند. اقدام درست؟",o:["انتظار طبق برچسب سازنده و اندازه‌گیری ولتاژ باس DC با ابزار رتبه‌دار","نمایشگر خاموش یعنی تخلیه کامل است و باز کردن مجاز است","اتصال کوتاه ترمینال‌ها با پیچ‌گوشتی برای تخلیه","آزمون ولتاژ ورودی سه فاز به‌تنهایی کافی است"],a:0,e:"خازن‌های باس DC دقایقی پس از قطع شارژ می‌مانند و نمایشگر نشانگر تخلیه نیست. اتصال کوتاه با ابزار نامناسب خطر قوس ایجاد می‌کند و ورودی صفر وضعیت باس را نشان نمی‌دهد.",r:"IEC 61800-5-1; NFPA 70E",d:"HSEW-20",g:"B",w:10},{id:"e067",t:"آزمون نبود ولتاژ",q:"کدام ترتیب برای تأیید نبود ولتاژ پیش از تماس صحیح است؟",o:["فقط آزمون مدار هدف با دو ولت‌متر متفاوت","آزمون روی منبع زندهٔ معلوم، آزمون مدار هدف، آزمون مجدد منبع معلوم","آزمون مدار هدف و تطبیق با نمودار تک‌خطی","بررسی موقعیت کلید و چراغ نشانگر تابلو"],a:1,e:"آزمون زنده-مرده-زنده ثابت می‌کند ولت‌متر سالم است و عدد صفر واقعی است. نشانگر تابلو و نمودار می‌توانند اشتباه یا قدیمی باشند.",r:"NFPA 70E Art. 120",d:"HSEW-20",g:"B",w:10},{id:"e068",t:"اولویت ISO ۱۲۱۰۰",q:"در مرحلهٔ طراحی/بازطراحی همزن، برای محور چرخان که نیاز به دسترسی ندارد، کدام اقدام در سلسله‌مراتب ISO ۱۲۱۰۰ اولویت بالاتری دارد؟",o:["نصب حفاظ ثابت روی محور","نصب علامت هشدار و آموزش اپراتور","الزام عینک و لباس چسبان","طراحی ذاتاً ایمن: حذف نیاز دسترسی مثلاً با نقطهٔ روغن‌کاری بیرونی و پوشش یکپارچه"],a:3,e:"طراحی ذاتاً ایمن مرحلهٔ اول است و خطر را حذف می‌کند؛ حفاظ مرحلهٔ دوم، و علائم و آموزش و PPE مراحل بعدی با کمترین اثربخشی‌اند.",r:"ISO 12100",d:"HSEW-22",g:"B",w:8},{id:"e069",t:"اینترلاک ساده",q:"سانتریفیوژ پس از قطع ۴۰ ثانیه می‌چرخد، ولی حفاظ با اینترلاک ساده در ۳ ثانیه باز می‌شود. راه‌حل؟",o:["قفل حفاظ تا توقف کامل یا تأخیر همراه پایش حرکت صفر","برچسب هشدار «۴۰ ثانیه صبر کنید»","حسگر نزدیکی ساده و دکمهٔ توقف اضطراری","سوئیچ اینترلاک دوم به‌صورت موازی"],a:0,e:"مشکل، بازشدن حفاظ در حین حرکت خطرناک است و اینترلاک ساده فقط فرمان توقف می‌دهد. اضافه‌کردن سوئیچ یا برچسب زمان باز شدن را کنترل نمی‌کند.",r:"ISO 14119",d:"HSEW-22",g:"B",w:8},{id:"e070",t:"فاصلهٔ سیلندرها",q:"در کارگاه، سیلندر اکسیژن ۳ m از سیلندر استیلن بدون مانع ذخیره شده است. حداقل الزام؟",o:["۳ m کافی است اگر هر دو زنجیر شده باشند","فقط ۱٫۵ m فاصله کافی است","فقط دور بودن از منبع جرقه کافی است","حداقل ۶ m فاصله یا دیوار ۱٫۵ m با مقاومت آتش نیم‌ساعته"],a:3,e:"نشت اکسیژن شدت آتش استیلن را شدیداً افزایش می‌دهد؛ OSHA و NFPA ۵۱ جداسازی ۲۰ فوت یا مانع ۵ فوتی با مقاومت نیم‌ساعته را می‌خواهند. زنجیر فقط از افتادن جلوگیری می‌کند.",r:"OSHA 1926.350(a)(10); NFPA 51",d:"HSEW-16",g:"B",w:1},{id:"e071",t:"فشار استیلن",q:"اپراتور برای شعلهٔ داغ‌تر، تنظیم‌کنندهٔ استیلن را روی ۲ bar می‌گذارد و می‌گوید سیلندر با استون پر است. ارزیابی؟",o:["بی‌خطر است چون استون آن را پایدار می‌کند","خطرناک است؛ استیلن آزاد بالای حدود ۱ bar (۱۵ psig) ناپایدار و قابل تجزیهٔ انفجاری است","فقط شعله برگشتی خطر دارد و فلش‌بک‌آرستر کافی است","تا ۵ bar مجاز است چون فشار سیلندر ۱۵ bar است"],a:1,e:"استیلن در فشار آزاد بالای ۱۵ psig ممکن است بدون اکسیژن تجزیه شود؛ استون فقط در سیلندر و محیط متخلخل پایداری می‌دهد. فلش‌بک‌آرستر از تجزیهٔ مسیر لوله جلوگیری نمی‌کند.",r:"OSHA 1910.253(b)(2); NFPA 51",d:"HSEW-16",g:"B",w:1},{id:"e072",t:"قفل پیمانکار",q:"در تعمیرات اساسی، پیمانکار می‌خواهد روی پمپ‌های اسید با سیستم قفل خودش کار کند. بهترین رویکرد؟",o:["هر گروه سیستم قفل خودش را بدون هماهنگی اجرا کند","فقط قفل کارفرما بزند و پیمانکار قفل نداشته باشد","رویهٔ هماهنگ‌شده: قفل پیمانکار روی هسپ گروهی با رویهٔ کارفرما","پیمانکار قفل بزند و کلید را به سرپرست کارفرما بدهد"],a:2,e:"رویهٔ قفل باید برای کارفرما و پیمانکار یکپارچه و آگاهانه باشد؛ هر فرد باید قفل شخصی خودش را داشته باشد. دادن کلید به دیگران حفاظت شخصی را از بین می‌برد.",r:"OSHA 1910.147(f)(2),(f)(3)",d:"HSEW-28",g:"B",w:14},{id:"e073",t:"مسئولیت پیمانکار",q:"پیمانکار تمیزکاری مخزن، JSA خودش را تحویل داده است. کدام مسئولیت کارفرما قابل‌واگذاری نیست؟",o:["هیچ‌چیز؛ ارزیابی ریسک کار کاملاً با پیمانکار است","اطلاع‌رسانی مخاطرات ویژهٔ سایت (اسید باقی‌مانده، NOx) و هماهنگی کنترل‌ها","فقط دریافت بیمه‌نامه و ثبت‌نام","اتکا به صفر بودن TRIR پیمانکار"],a:1,e:"ISO ۴۵۰۰۱ هماهنگی شناسایی خطرات و کنترل ریسک متقابل با پیمانکار را از سازمان می‌خواهد. شاخص‌های گذشته‌نگر مثل TRIR صفر دانش خطرات خاص سایت را نمی‌رساند.",r:"ISO 45001 §8.1.4.2",d:"HSEW-28",g:"B",w:14},{id:"e074",t:"بستن تلفنی مجوز",q:"پیمانکار پس از پایان تعمیر خط اسید، مجوز را تلفنی می‌بندد و عملیات فردا صبح ایزولاسیون را بدون بازدید برمی‌دارد. نقص اصلی؟",o:["نبود بازدید مشترک و تأیید آمادگی تجهیز پیش از ابطال و رفع ایزولاسیون","نبود تأیید مدیر ارشد","نبود ثبت ساعت دقیق پایان کار","نبود بایگانی نسخهٔ فیزیکی مجوز"],a:0,e:"بستن بدون بازدید، ابزار جامانده، فلنج بدون پیچ یا بلایند فراموش‌شده را نمی‌بیند و ایزولاسیون برداشته می‌شود؛ مدیر ارشد یا بایگانی حل‌کنندهٔ ریسک راه‌اندازی نیست.",r:"HSE UK HSG250",d:"HSEW-28",g:"B",w:14},{id:"e075",t:"نمونه‌برداری فیوم",q:"برای ارزیابی مواجههٔ جوشکار استنلس‌استیل با Cr(VI)، پمپ نمونه‌بردار را کجا قرار می‌دهید؟",o:["روی پایه ۱ m از قوس","دور از جوشکار برای نمایندگی تهویهٔ عمومی","روی پیشانی خارج از کلاه","داخل کلاه جوشکار نزدیک ناحیهٔ تنفس"],a:3,e:"نمونه باید غلظت واقعی نفس شخص را نشان دهد؛ کلاه جوشکار فیوم را متفاوت از بیرون کلاه می‌کند. نمونه‌برداری ایستا یا بیرون کلاه مواجهه را معمولاً اشتباه تخمین می‌زند.",r:"EN ISO 10882-1; OSHA 1910.1026",d:"HSEW-15",g:"B",w:1},{id:"e076",t:"دو نفر روی یک نقطه",q:"دو کارگر می‌خواهند به یک تیر فولادی با استحکام تأییدشدهٔ ۲۵ kN وصل شوند. ارزیابی؟",o:["بله؛ ۲۵ kN از ۲۲٫۲ kN بیشتر است","بله؛ هر نفر جاذب انرژی دارد","نه؛ برای دو نفر حدود ۴۴ kN لازم است یا طراحی مهندسی با ضریب ۲","بله اگر مجموع وزن دو نفر زیر ۲۰۰ kg باشد"],a:2,e:"حداقل ۵۰۰۰ lbf برای هر نفر نیاز است: ۲×۲۲٫۲ ≈ ۴۴٫۵ kN. وجود جاذب یا وزن کم، نیرو را کاهش نمی‌دهد و استحکام نقطه باید برای اثر ایست باشد.",r:"OSHA 1926.502(d)(15)",d:"HSEW-13",g:"B",w:7},{id:"e077",t:"آویختگی",q:"کارگر پس از سقوط در هارنس آویزان و هشیار است و اورژانس ۲۰ دقیقه دورتر است. اولین تصمیم؟",o:["منتظر اورژانس بماند تا آسیب ستون فقرات نشود","فقط به کارگر بگویید آرام باشد","اجرای فوری نجات طبق برنامهٔ از پیش تعیین‌شده و فراخوان اورژانس همزمان","فقط دستگاه را اطلاع دهند و دور بایستند"],a:2,e:"ماندن در هارنس خطر تروما آویختگی دارد و نجات سریع باید برنامه‌ریزی شده باشد. انتظار برای اورژانس بیرونی پذیرفته نیست و OSHA نجات فوری را الزام می‌کند.",r:"OSHA 1926.502(d)(20); SHIB 03-24-2004",d:"HSEW-13",g:"B",w:7},{id:"e078",t:"زاویهٔ نردبان",q:"نردبان برای رسیدن به تکیه‌گاه ۶ m ارتفاع، پایش ۲ m از دیوار قرار گرفته است. ارزیابی؟",o:["مسطح‌تر از ۴:۱ است (≈۷۲°)؛ پا باید حدود ۱٫۵ m باشد","۴:۱ رعایت شده چون ۶ تقسیم بر ۲ بزرگ‌تر از ۴ است","زاویه تندتر از حد است و پا باید دورتر باشد","قابل‌قبول است؛ هرچه مسطح‌تر پایدارتر"],a:0,e:"۴:۱ یعنی پا ۶/۴ = ۱٫۵ m. نسبت ۶:۲ = ۳:۱ است و ≈۷۲° می‌دهد؛ زاویهٔ مسطح‌تر خطر لغزش پایه و خمش نردبان را بالا می‌برد.",r:"OSHA 1926.1053(b)(5)",d:"HSEW-18",g:"B",w:7},{id:"e079",t:"تنزل فضای بسته",q:"هاپر کیک نیکل (مواد جامد جاری) آزمون شده: O2 و LEL مناسب‌اند. تیم می‌خواهد آن را غیرمجوزدار اعلام کند. تصمیم؟",o:["مجاز است اگر اتمسفر آزمون و ثبت شود","مجوزدار می‌ماند؛ خطر غرق‌شدگی با تهویه یا آزمون اتمسفر کنترل نمی‌شود","مجاز است اگر مدت ورود زیر ۱۵ دقیقه باشد","مجاز است اگر نگهبان بیرونی بگذارند"],a:1,e:"تنزل (c)(۵) فقط برای فضایی است که تنها خطر آن اتمسفری است و با تهویه به‌تنهایی کنترل می‌شود. خطر غرق‌شدگی در مواد جامد مستقل از اتمسفر است.",r:"OSHA 1910.146(b),(c)(5)",d:"HSEW-01",g:"B",w:5},{id:"e080",t:"بازیابی عمودی",q:"ورود عمودی به مخزن ۶ m با فقط طناب ایمنی دستی و دو نفر برنامه‌ریزی شده است. نقص؟",o:["نقصی نیست؛ دو نفر برای کشیدن کافی‌اند","با دستگاه تنفس مستقل نیازی به بازیابی نیست","فقط در اتمسفر IDLH بازیابی لازم است","برای عمق بیش از ۱٫۵ m باید سیستم بازیابی مکانیکی مثل سه‌پایه و وینچ باشد"],a:3,e:"برای ورود عمودی عمیق‌تر از ۵ فوت (۱٫۵ m) دستگاه مکانیکی بازیابی لازم است. وجود SCBA یا غیر IDLH بودن اتمسفر الزام بازیابی را برنمی‌دارد.",r:"OSHA 1910.146(k)(3)",d:"HSEW-01",g:"B",w:5},{id:"e081",t:"محاسبه LTIFR",q:"در یک سال، ۱۸۰ کارمند هر کدام ۲۰۰۰ ساعت و پیمانکاران جمعاً ۴۰٬۰۰۰ ساعت کار کرده‌اند و ۲ مورد LTI ثبت شده است. LTIFR بر مبنای ۱٬۰۰۰٬۰۰۰ ساعت (با احتساب پیمانکاران) چقدر است؟",o:["۵٫۵۶","۵٫۰","۱٫۰","۱۱٫۱"],a:1,e:"ساعت کل ۴۰۰٬۰۰۰ است و ۲×۱٬۰۰۰٬۰۰۰÷۴۰۰٬۰۰۰ = ۵٫۰. عدد ۵٫۵۶ پیمانکاران را حذف می‌کند و ۱٫۰ مبنای ۲۰۰٬۰۰۰ را به کار برده است.",r:"ILO; OSHA 1904",g:"C",w:13},{id:"e082",t:"محاسبه TRIR",q:"واحدی در یک سال ۲۵۰٬۰۰۰ ساعت کار و ۴ مورد قابل‌ثبت OSHA داشته است. TRIR چقدر است؟",o:["۱۶","۱٫۶","۰٫۸","۳٫۲"],a:3,e:"TRIR = ۴×۲۰۰٬۰۰۰÷۲۵۰٬۰۰۰ = ۳٫۲. عدد ۱۶ با مبنای ۱٬۰۰۰٬۰۰۰ به دست می‌آید و با TRIR تعریف‌شده در OSHA سازگار نیست.",r:"OSHA 29 CFR 1904",g:"C",w:13},{id:"e083",t:"محاسبه LOPA",q:"رویداد آغازگر ۰٫۱ بار در سال رخ می‌دهد. IPL اول (پاسخ اپراتور با آلارم مستقل) PFD برابر ۰٫۱ و IPL دوم (شیر اطمینان) PFD برابر ۰٫۰۱ دارد. ریسک هدف ۰٫۰۰۰۰۱ در سال است. حداقل RRF اضافی لازم چقدر است؟",o:["۱۰","۱۰۰","۱ (نیازی نیست)","۱۰۰۰"],a:0,e:"فرکانس کاهش‌یافته = ۰٫۱×۰٫۱×۰٫۰۱ = ۰٫۰۰۰۱ در سال؛ نسبت به هدف ۰٫۰۰۰۰۱ باید ۱۰ برابر دیگر کاهش یابد. «نیازی نیست» اشتباه است چون فرکانس ۱۰ برابر هدف است.",r:"CCPS LOPA",g:"C",w:11},{id:"e084",t:"استقلال IPL",q:"در LOPA رویداد آغازگر «خرابی حلقه‌ی کنترل دمای اتوکلاو در DCS» است. تیم آلارم دمای بالا از همان ترنسمیتر و کارت ورودی DCS را به‌همراه پاسخ اپراتور به‌عنوان IPL می‌خواهد. تصمیم درست؟",o:["اعتبار دارد چون اپراتور مستقل از کنترل‌کننده است","با PFD برابر ۰٫۱ اعتبار کامل می‌گیرد","اعتبار دارد اگر آلارم صوتی بلند باشد","اعتبار ندارد؛ حسگر و ورودی مشترک است و باید حفاظ مستقل (مثلاً SIS) داشت"],a:3,e:"IPL باید از رویداد آغازگر مستقل باشد؛ با حسگر و I/O مشترک، همان خرابی هر دو را از کار می‌اندازد. بلندی آلارم یا استقلال اپراتور این وابستگی را برطرف نمی‌کند.",r:"CCPS LOPA; IEC 61511",g:"C",w:11},{id:"e085",t:"صفر LTI و تصمیم مدیریتی",q:"مدیر عامل می‌گوید «سه سال بدون LTI داریم، پس ریسک کنترل شده است؛ HAZOP هال انحلال را عقب بیندازیم». بهترین پاسخ حرفه‌ای شما؟",o:["موافقت می‌کنم چون سابقه نشان‌دهنده‌ی کنترل مؤثر است","HAZOP را به شرط کاهش دامنه به گره‌های پرخطر عقب می‌اندازم","نتایج HAZOP قبلی سایر کارخانه‌ها را جایگزین می‌کنم","LTI رویداد نادر فرایندی را پیش‌بینی نمی‌کند؛ با شاخص‌های فرایندی (API 754) ضرورت HAZOP را توجیه می‌کنم"],a:3,e:"جراحت‌های شخصی و رویدادهای فرایندی با علل و فراوانی متفاوت رخ می‌دهند؛ صفر LTI درباره‌ی سلامت لایه‌های حفاظتی فرایند چیزی نمی‌گوید. انتظار برای LTI یعنی انتظار برای پیامد.",r:"CCPS Metrics; API RP 754",g:"C",w:13},{id:"e086",t:"احتمال صفر LTI",q:"کارخانه‌ای ۱۵۰٬۰۰۰ ساعت در سال کار می‌کند و میانگین صنعت LTIFR برابر ۳ (در ۱٬۰۰۰٬۰۰۰ ساعت) است. اگر دقیقاً مثل میانگین باشد، احتمال صفر LTI در یک سال (توزیع پواسون) تقریباً چقدر است؟",o:["حدود ۵۵٪","حدود ۳۶٪","حدود ۶۴٪","حدود ۹۰٪"],a:2,e:"تعداد مورد انتظار ۰٫۴۵ است و احتمال صفر = e^-۰٫۴۵ ≈ ۰٫۶۴. عدد ۵۵٪ تقریب خطی نادرست و ۳۶٪ احتمال دست‌کم یک مورد است.",r:"Poisson statistics",g:"C",w:13},{id:"e087",t:"خطای انسانی به‌عنوان ریشه",q:"گزارش اولیه می‌گوید اپراتور شیر اشتباه را باز کرد و پیشنهاد می‌کند «آموزش مجدد». شیرها دقیقاً یک‌شکل‌اند، برچسبی ندارند و نقشه در دسترس نبوده است. کدام قضاوت درست است؟",o:["علت ریشه‌ای خطای انسانی است و آموزش کافی است","باید اپراتور را ابتدا تنبیه و سپس سیستم را بررسی کرد","خطای اپراتور نقطه‌ی شروع تحقیق است؛ علل ریشه‌ای در برچسب‌گذاری، نقشه و رویه‌اند","چون شیرها یک‌شکل‌اند، حادثه اجتناب‌ناپذیر بوده است"],a:2,e:"وقتی شرایط کاری خطا را محتمل می‌کند، آموزش مجدد فقط فرد را هدف می‌گیرد و شرایط باقی می‌ماند. تحقیق باید پرسید چرا سیستم اجازه‌ی این خطا را داد.",r:"CCPS Incident Investigation; Reason",g:"C",w:12},{id:"e088",t:"محدودیت پنج‌چرا",q:"دو تیم همان نشت اسید را با پنج‌چرا تحلیل کردند و یکی به «بی‌توجهی اپراتور» و دیگری به «نبود برنامه‌ی بازرسی مخزن» رسید. چه نتیجه‌ای درست است؟",o:["تیم دوم درست است چون ریشه‌ی عمیق‌تری یافته","پنج‌چرا به قضاوت تحلیلگر وابسته است؛ علل باید با شواهد راستی‌آزمایی شوند","تیم اول درست است چون علت انسانی همیشه مقدم است","پنج‌چرا بی‌اعتبار است و نباید به کار رود"],a:1,e:"پنج‌چرا خطی است و بدون شواهد، هر تیم می‌تواند شاخه‌ی متفاوتی بگیرد. عمیق‌تر بودن لزوماً درست‌تر بودن نیست و ابزار همچنان مفید است ولی باید با شواهد پشتیبانی شود.",r:"CCPS Incident Investigation",g:"C",w:12},{id:"e089",t:"حفظ شواهد",q:"پس از نشت H2S در هال بازیافت، محل ایمن شد و تولید می‌خواهد فوراً راه‌اندازی کند. پیش از بازگرداندن تجهیز به سرویس، کدام اقدام اولویت دارد؟",o:["ثبت موقعیت شیرها و کلیدها، عکس و ذخیره‌ی لاگ DCS و دتکتور","راه‌اندازی برای بازتولید نشت و دیدن علت","تمیزکاری کامل و سپس عکس‌برداری","تکمیل گزارش بر اساس حافظه‌ی شاهدان"],a:0,e:"لاگ‌ها قابل بازنویسی و وضعیت شیرها قابل تغییرند، پس مستندسازی پیش از هر دستکاری لازم است. بازتولید نشت خطرناک است و تمیزکاری شواهد را نابود می‌کند.",r:"CCPS Incident Investigation",d:"HSEW-27",g:"C",w:12},{id:"e090",t:"مصاحبه با شاهدان",q:"پس از حادثه، سرپرست پیشنهاد می‌دهد شاهدان در یک جلسه جمع شوند تا روایت واحد تنظیم شود. بهترین روش تحقیق چیست؟",o:["پذیرفتن جلسه‌ی مشترک برای صرفه‌جویی در زمان","گرفتن فقط اظهار مسئول شیفت","مصاحبه پس از یک هفته تا شاهدان آرام شوند","مصاحبه‌ی جداگانه و زودهنگام با پرسش‌های باز، سپس تطبیق روایت‌ها"],a:3,e:"روایت مشترک اثر القای متقابل دارد و تفاوت‌های مهم را پنهان می‌کند. حافظه با گذر زمان تغییر می‌کند و مصاحبه‌ی جداگانه و زودهنگام شواهد معتبرتری می‌دهد.",r:"CCPS Incident Investigation",g:"C",w:12},{id:"e091",t:"بستن عدم‌انطباق",q:"عدم‌انطباق «مجوز کار گرم بدون تست گاز» با آموزش مجدد کارکنان و امضای حضور در همان هفته بسته شد. کدام معیار برای تأیید اثربخشی مناسب‌تر است؟",o:["وجود برگه‌ی حضور آموزش","نمره‌ی قبولی آزمون پس از آموزش","تأیید شفاهی سرپرست که اجرا می‌شود","بررسی نمونه‌ی مجوزهای چند ماه بعد و مشاهده‌ی میدانی تست گاز"],a:3,e:"اثربخشی یعنی ثابت شدن عدم‌تکرار در عمل، نه انجام اقدام. حضور و نمره فقط یادگیری را نشان می‌دهند و رفتار را تضمین نمی‌کنند.",r:"ISO 45001 §10.2",d:"HSEW-14",g:"C",w:13},{id:"e092",t:"اقدام اصلاحی در برابر اصلاح",q:"در ممیزی معلوم شد کالیبراسیون سه دتکتور H2S منقضی شده است. کدام اقدام «اقدام اصلاحی» برای علت ریشه‌ای است (نه صرفاً اصلاح)؟",o:["ایجاد زمان‌بندی کالیبراسیون با هشدار خودکار و مسئول مشخص پس از ریشه‌یابی","کالیبره‌ی فوری هر سه دتکتور","خارج از سرویس اعلام کردن دتکتورهای منقضی","ثبت یادداشت در گزارش ممیزی"],a:0,e:"کالیبره کردن و علامت‌گذاری رفع نشانه‌اند و علت ایجاد تأخیر را از بین نمی‌برند. اقدام اصلاحی باید از تکرار در دتکتورهای بعدی جلوگیری کند.",r:"ISO 45001 §10.2",g:"C",w:13},{id:"e093",t:"بای‌پس موقت",q:"پمپ آمونیاک هنگام راه‌اندازی به‌خاطر تریپ فشار پایین مدام متوقف می‌شود و تعمیرکار پیشنهاد می‌کند دو هفته جامپر روی تریپ بگذارند و فقط در دفتر شیفت ثبت شود. تصمیم درست؟",o:["MOC موقت با ارزیابی ریسک، اقدام جبرانی، تأیید و تاریخ انقضا","مجاز است چون کمتر از ۳۰ روز است","مجاز است اگر اپراتور دائم کنار پمپ بایستد","مجاز است اگر سرپرست شیفت شفاهاً موافقت کند"],a:0,e:"بای‌پس سامانه‌ی حفاظتی تغییر است و بدون MOC موقت لایه‌ی حفاظتی بی‌صدا حذف می‌شود. قاعده‌ی «زیر ۳۰ روز» در این الزام استاندارد وجود ندارد.",r:"ISO 45001 §8.1.3; CCPS RBPS (MOC)",d:"HSEW-22",g:"C",w:14},{id:"e094",t:"تشخیص نیاز به MOC",q:"کدام مورد نیاز به فرایند مدیریت تغییر دارد؟",o:["تعویض ترنسمیتر خراب با همان مدل و رنج","تعویض واشر با همان جنس و مشخصات","ورود خوراک کیک نیکل از منبع جدید با ترکیب نامشخص به مرحله‌ی انحلال","تعویض بلبرینگ پمپ با همان مشخصات"],a:2,e:"تغییر ترکیب خوراک می‌تواند واکنش، گازهای تولیدی و خوردگی را تغییر دهد و جزو تغییر فرایند است. سه گزینه‌ی دیگر جایگزینی مشابه (replacement in kind) هستند.",r:"ISO 45001 §8.1.3; CCPS RBPS (MOC)",d:"HSEW-01",g:"C",w:14},{id:"e095",t:"سلسله‌مراتب کنترل",q:"در بسته‌بندی پودر اکسید نیکل گرد و غبار زیاد است. کدام اقدام در سلسله‌مراتب کنترل بالاتر قرار دارد؟",o:["نصب LEV در محل تخلیه‌ی کیسه","تعویض دوره‌ای کارکنان برای کاهش مواجهه","تغییر فرایند به دانه‌بندی یا پودر مرطوب تا غبار تولید نشود","الزام ماسک با فیلتر مناسب"],a:2,e:"حذف یا جایگزینی منبع غبار، خطر را از ریشه کم می‌کند. LEV کنترل مهندسی، تعویض کارکنان اداری و ماسک PPE است و همگی پایین‌ترند.",r:"ISO 45001 §8.1.2",d:"HSEW-24",g:"C",w:4},{id:"e096",t:"تله‌ی ماتریس ریسک",q:"در ارزیابی، ریسک A (احتمال ۵، شدت ۱) و ریسک B (احتمال ۱، شدت ۵: امکان مرگ) هر دو امتیاز ۵ و رنگ زرد گرفتند. اقدام درست؟",o:["هر دو یکسان‌اند و با همان اولویت رسیدگی می‌شوند","A اولویت دارد چون احتمال بالاتری دارد","B را جداگانه با بررسی سدها یا LOPA ارزیابی می‌کنم","B نادر است و فعلاً نیازی به بررسی ندارد"],a:2,e:"ضرب رتبه‌ها پیامد مرگ‌بار نادر را با جراحت جزئی مکرر هم‌ارز می‌کند. پیامدهای شدید به بررسی ویژه نیاز دارند حتی اگر امتیاز پایین باشد.",r:"ISO 31010; CCPS RBPS",g:"C",w:11},{id:"e097",t:"تصمیم ALARP",q:"ریسک سرریز مخزن اسید در ناحیه‌ی تحمل‌پذیر است. افزودن کلید سطح بالای مستقل با هزینه‌ی ناچیز نسبت به پیامد قابل پیشگیری پیشنهاد شده است. با منطق ALARP چه می‌کنید؟",o:["لازم نیست چون ریسک در ناحیه‌ی تحمل‌پذیر است","فقط اگر قانون صریحاً الزام کند","اجرا می‌شود چون هزینه به‌طور فاحش نامتناسب با فایده نیست","پس از اولین سرریز اجرا می‌شود"],a:2,e:"در ناحیه‌ی تحمل‌پذیر هم باید تا حد ALARP کاهش داد مگر آنکه هزینه فاحشاً نامتناسب باشد. «تحمل‌پذیر بودن» پایان تعهد نیست.",r:"UK HSE R2P2 (ALARP)",g:"C",w:11},{id:"e098",t:"رفتار در جلسه‌ی HAZOP",q:"در جلسه‌ی HAZOP، تیم ۴۰ دقیقه روی طراحی مجدد خط تخلیه‌ی شیر اطمینان بحث می‌کند و گره‌های دیگر عقب مانده‌اند. تسهیلگر چه کند؟",o:["جلسه را تا نهایی شدن طراحی ادامه دهد","گره را رد کند تا زمان حفظ شود","شدت پیامد را پایین‌تر ثبت کند تا بحث تمام شود","پیشنهاد را با مسئول ثبت کند و بحث طراحی را به خارج از جلسه ببرد"],a:3,e:"HAZOP برای شناسایی و ثبت توصیه است، نه طراحی در جلسه. طراحی طولانی مشارکت‌کنندگان را خسته و پوشش گره‌ها را ناقص می‌کند.",r:"IEC 61882",g:"C",w:11},{id:"e099",t:"نقشه‌ی ورودی HAZOP",q:"می‌خواهید برای هال انحلال HAZOP انجام دهید ولی P&ID موجود نیست. اولین قدم؟",o:["شروع HAZOP با طرح دست‌کشیده‌ی اپراتور بدون تأیید","انجام HAZOP بر پایه‌ی حافظه‌ی شفاهی تیم","جایگزین کردن HAZOP با چک‌لیست عمومی","پیمایش میدانی و تهیه‌ی P&ID as-built تأییدشده توسط اپراتور و فرایندی"],a:3,e:"HAZOP روی تجهیزات و خطوط نقشه انجام می‌شود و نقشه‌ی غلط نتیجه‌ی غلط می‌دهد. نقشه‌ی تأییدنشده یا حافظه، شیرها و بای‌پس‌های ثبت‌نشده را از قلم می‌اندازد.",r:"IEC 61882; CCPS PHA",d:"HSEW-01",g:"C",w:11},{id:"e100",t:"بازنگری PHA",q:"PHA واحدی پنج سال پیش انجام شد و بعد از آن تغییر بزرگی در خط اسید با MOC و بررسی مختصر اعمال شد. طبق رویکرد OSHA PSM، بازنگری و اعتبارسنجی کامل PHA چه زمانی باید باشد؟",o:["دست‌کم هر ۵ سال از PHA قبلی؛ MOC تقویم را از نو شروع نمی‌کند","۵ سال پس از تاریخ آخرین MOC","۱۰ سال از PHA قبلی اگر حادثه‌ای رخ نداده","۳ سال پس از هر تغییر بزرگ"],a:0,e:"OSHA ۱۹۱۰.۱۱۹(e)(۶) بازنگری دست‌کم هر ۵ سال را می‌خواهد و بررسی ریسک تغییر جدا از آن در MOC انجام می‌شود. نبود حادثه مهلت را طولانی نمی‌کند.",r:"OSHA 1910.119(e)(6)",g:"C",w:11},{id:"e101",t:"اولویت‌بندی FMEA",q:"حالت خرابی A: شدت ۹، وقوع ۲، کشف ۲ (RPN=۳۶)؛ حالت B: شدت ۳، وقوع ۶، کشف ۵ (RPN=۹۰). با رویکرد اولویت‌دهی مبتنی بر شدت (Action Priority) کدام درست است؟",o:["B اول است چون RPN بزرگ‌تر دارد","A را اول بررسی می‌کنم چون شدت بالاست و RPN پایین از ضرب است","هر دو برابرند چون مجموع رتبه‌هایشان نزدیک است","تا RPN از ۱۰۰ نگذرد اقدامی لازم نیست"],a:1,e:"ضرب سه رتبه، شدت بالا را رقیق می‌کند و AIAG-VDA به شدت و ترکیب‌هایش اولویت می‌دهد. آستانه‌ی ثابت مثل ۱۰۰ دلیل فنی ندارد.",r:"AIAG-VDA FMEA 2019",g:"C",w:11},{id:"e102",t:"استقلال سدها",q:"در Bow-tie نشت H2S شش سد پیشگیرانه رسم شده ولی چهارتای آنها «اپراتور آلارم را می‌بیند و واکنش می‌دهد» است. ضعف اصلی چیست؟",o:["وابستگی مشترک به عملکرد انسانی؛ تعداد سد معادل اثربخشی نیست","تعداد سدها بیش از حد است و باید کم شود","سمت راست باید سدهای بیشتری داشته باشد","هیچ ضعفی نیست چون شش سد وجود دارد"],a:0,e:"سدهایی که همگی به یک عملکرد انسانی وابسته‌اند مستقل نیستند و با یک خطا هم‌زمان می‌شکنند. شمار سد بدون استقلال و اثربخشی ایمنی نمی‌آورد.",r:"CCPS Bow-tie; ISO 31010",g:"C",w:11},{id:"e103",t:"افت گزارش شبه‌حادثه",q:"گزارش ماهانه‌ی شبه‌حادثه از ۴۰ به ۵ رسید، چند هفته پس از توبیخ اپراتوری که خطای خودش را گزارش کرده بود. تفسیر درست؟",o:["ایمنی بهتر شده و باید هدف گزارش را کم کرد","تعداد حادثه‌ها واقعاً هشت برابر کم شده","فقط باید جلسه‌ی انگیزشی گذاشت","احتمالاً گزارش‌دهی سرکوب شده و باید اعتماد و فرهنگ عادلانه بازسازی شود"],a:3,e:"افت ناگهانی همزمان با اقدام تنبیهی نشانه‌ی ترس است. مدیریت باید تنبیه خطای گزارش‌شده را بازنگری و بازخورد مثبت بدهد.",r:"Reason; CCPS RBPS",g:"C",w:12},{id:"e104",t:"نرمال‌سازی انحراف",q:"در بازدید متوجه می‌شوید سال‌هاست برای رفع گرفتگی خط دوغاب نیکل بدون LOTO «سریع» کار می‌کنند و حادثه‌ای نبوده است. بهترین تحلیل؟",o:["مشکلی نیست چون سال‌ها حادثه نداشته","همه‌ی کارکنان را فوراً تنبیه می‌کنم","نرمال‌سازی انحراف؛ علل سیستمی (دسترسی، فشار تولید، نظارت) را اصلاح می‌کنم","یک یادآوری شفاهی در توک‌باکس کافی است"],a:2,e:"انحراف بدون پیامد عادی می‌شود، ولی ریسک باقی است. اگر علت سیستمی (مثلاً نبود نقطه‌ی قفل در دسترس) رفع نشود، تنبیه و یادآوری موقتی‌اند.",r:"Vaughan 1996; OSHA 1910.147",d:"HSEW-22",g:"C",w:12},{id:"e105",t:"علت پنهان",q:"شلنگ انتقال اسید پاره شد و اسید پاشید؛ بعداً معلوم شد شلنگ‌ها در هیچ فهرست بازرسی نیستند و مسئولی ندارند. کدام «علت پنهان» (latent) است؟",o:["پاره شدن شلنگ","نبود برنامه‌ی بازرسی و مسئول برای شلنگ‌ها","پاشیده شدن اسید روی کارگر","استفاده‌نکردن کارگر از شیلد"],a:1,e:"پارگی و پاشش نتیجه‌ی مستقیم‌اند و علت پنهان نقص سیستمی است که مدت‌ها قبل وجود داشته. شیلد لایه‌ی حفاظتی آخر است و نبودش علت ریشه‌ای نیست.",r:"Reason 1997; CCPS Incident Investigation",d:"HSEW-23",g:"C",w:12},{id:"e106",t:"خط زمانی تحقیق",q:"در بررسی افزایش فشار اتوکلاو، تیم می‌خواهد خط زمانی را از لحظه‌ی آلارم فشار بالا شروع کند. بهترین رویکرد؟",o:["شروع از آلارم چون پیش از آن رویدادی نیست","شروع از ساعت‌ها یا روزها قبل: تعمیرات، تغییر تنظیمات و تحویل شیفت","فقط از اظهار ارشدترین شاهد و بقیه را تطبیق دادن","فقط داده‌ی DCS چون شاهد قابل اعتماد نیست"],a:1,e:"علل پنهان اغلب پیش از رویداد کاشته می‌شوند و منابع مستقل باید تطبیق داده شوند. هم داده‌ی DCS و هم شاهدان لازم‌اند و هیچ‌کدام به‌تنهایی کافی نیست.",r:"CCPS Incident Investigation",g:"C",w:12},{id:"e107",t:"سطح رفتار در کرک‌پاتریک",q:"پس از آموزش انتقال اسید، کدام اندازه‌گیری «سطح ۳ کرک‌پاتریک» (رفتار) است؟",o:["نمره‌ی آزمون پایان دوره","فرم رضایت از مدرس","مشاهده‌ی میدانی چک‌لیست انتقال اسید توسط سرپرست چند هفته بعد","کاهش شمار پاشش اسید در سال"],a:2,e:"سطح ۳ تغییر رفتار در محل کار است. آزمون سطح ۲، رضایت سطح ۱ و کاهش حوادث سطح ۴ (نتایج) است.",r:"Kirkpatrick Model",g:"C",w:16},{id:"e108",t:"ارزیابی شایستگی",q:"مراقب فضای بسته آموزش ۴ ساعته‌ی تئوری دیده و آزمون کتبی را با ۹۰٪ گذرانده است. برای احراز شایستگی او برای کار واقعی کدام مدرک مناسب‌تر است؟",o:["گواهی حضور در آموزش","ارزیابی عملی مشاهده‌شده: کار با دتکتور، ارتباط و اقدام اضطراری","نمره‌ی کتبی بالاتر در آزمون دوم","تأیید شفاهی سرپرست"],a:1,e:"شایستگی یعنی توانایی انجام کار، که با نمایش عملی سنجیده می‌شود. حضور و نمره‌ی کتبی دانش را می‌سنجند نه توانایی اجرا.",r:"ISO 45001 §7.2",d:"HSEW-27",g:"C",w:16},{id:"e109",t:"اثربخشی کمیته‌ی ایمنی",q:"کمیته‌ی ایمنی هر ماه تشکیل می‌شود ولی ۷۰٪ مصوبات عقب مانده است. کدام تغییر بیشترین اثر را دارد؟",o:["افزایش تعداد اعضا","مالک و موعد برای هر مصوبه و پیگیری نرخ بسته شدن با ارجاع به مدیریت","کم کردن دفعات جلسه","دعوت از سخنران خارجی"],a:1,e:"ضعف در تبدیل تصمیم به اقدام است و پاسخگویی آن را برطرف می‌کند. تعداد اعضا یا سخنران مشکل پیگیری را حل نمی‌کند.",r:"ISO 45001 §5.4",g:"C",w:13},{id:"e110",t:"نتایج نظارت سلامت",q:"در معاینه‌ی دوره‌ای، نیکل ادرار چند نفر از یک هال انحلال بالاتر از مقدار مرجع پزشک طب کار است. اولین اقدام؟",o:["بررسی مواجهه در آن هال (راه پوست، تنفس، نظافت و آلودگی سطح) و کنترل منبع","فقط کنار گذاشتن افراد از کار","تکرار آزمایش تا نتیجه طبیعی شود","ثبت نتایج بدون اقدام چون فردی است"],a:0,e:"نتیجه‌ی غیرعادی گروهی یعنی کنترل مواجهه شکست خورده و باید منبع را یافت. کنار گذاشتن افراد منبع را برطرف نمی‌کند.",r:"ILO Health Surveillance Guidelines; ISO 45001 §9.1",g:"C",w:9},{id:"e111",t:"دامنه‌ی کنترل در ICS",q:"در نشت بزرگ، فرمانده‌ی حادثه ۱۸ نفر از گروه‌های مختلف را مستقیماً هدایت می‌کند و دستورها گم می‌شود. اقدام مناسب ICS؟",o:["افزایش تعداد رادیوها","تشکیل بخش‌ها و گروه‌ها تا هر سرپرست ۳ تا ۷ نفر را اداره کند","رفتن فرمانده به صحنه برای هدایت مستقیم","کاهش نیرو به ۱۰ نفر"],a:1,e:"دامنه‌ی کنترل مطلوب ۳ تا ۷ است و تفویض ساختاری آن را برطرف می‌کند. رفتن به صحنه، فرمانده را از نگاه کلی دور می‌کند.",r:"FEMA ICS-100",d:"HSEW-27",g:"C",w:15},{id:"e112",t:"انتخاب محل تجمع",q:"باد از شمال می‌وزد (به سمت جنوب). نشت آمونیاک در مرکز واحد بازیابی است. کدام محل تجمع مناسب است؟",o:["شمال واحد، بالادست باد و خارج از شعاع محاسبه‌ی پخش","۳۰۰ متر جنوب، نزدیک گیت اصلی","۵۰ متر جنوب‌شرقی کنار پارکینگ","داخل ساختمان اداری جنوب با درهای باز"],a:0,e:"تجمع باید بالادست یا عمود بر باد باشد. محل‌های جنوبی در مسیر ابر هستند و فاصله‌ی زیاد در پایین‌دست آن را ایمن نمی‌کند.",r:"CCPS ERP; NIOSH",d:"HSEW-27",g:"C",w:15},{id:"e113",t:"نخستین تمرین اضطراری",q:"کارخانه هرگز طرح اضطراری را تمرین نکرده و بیشتر کارکنان با ICS آشنا نیستند. بهترین نخستین گام؟",o:["تمرین مقیاس کامل سرزده با آتش‌نشانی","فقط تمرین تخلیه‌ی ساختمان","منتظر ماندن تا ممیزی بعدی","آموزش نقش‌ها و تمرین میزی یا پیاده‌روی سناریو، سپس تمرین عملکردی"],a:3,e:"نخست باید نقش‌ها و تصمیم‌ها آموزش و در شرایط کم‌خطر آزموده شود و پس از آن به مقیاس کامل رفت. تمرین سرزده بدون آمادگی خطرناک است.",r:"FEMA HSEEP",d:"HSEW-27",g:"C",w:15},{id:"e114",t:"یافته‌ی ارزیاب تمرین",q:"در تمرین، تخلیه ۴ دقیقه طول کشید ولی شمارش و تطبیق فهرست حاضران ۲۵ دقیقه. مهم‌ترین یافته‌ی ارزیاب کدام است؟",o:["تخلیه عالی بود و یافته‌ای نیست","آلارم بیش از حد بلند بود","ضعف پاسخ‌گویی به حضور و غیاب؛ فهرست به‌روز و مسئول مشخص لازم است","باید زمان تخلیه به ۳ دقیقه برسد"],a:2,e:"هدف تخلیه نجات جان است و بدون شمارش دقیق نمی‌دانید چه کسی در خطر است. سرعت تخلیه به‌تنهایی کافی نیست.",r:"FEMA HSEEP; ISO 45001 §8.2",d:"HSEW-27",g:"C",w:15},{id:"e115",t:"تفسیر شاخص پیمانکار",q:"پیمانکار A در سه سال ۶۰٬۰۰۰ ساعت کار و TRIR صفر دارد؛ پیمانکار B با ۲٬۰۰۰٬۰۰۰ ساعت TRIR برابر ۱٫۸ و سیستم HSE مستند دارد. کدام تفسیر درست است؟",o:["A ایمن‌تر است چون صفر دارد","B رد می‌شود چون بالاتر از ۱ است","صفر A با مواجهه‌ی کم آماری ضعیف است؛ هر دو را با ارزیابی سیستم و صلاحیت بسنجید","میانگین دو عدد معیار تصمیم است"],a:2,e:"با ۶۰٬۰۰۰ ساعت، فقط یک مورد قابل‌ثبت TRIR را به حدود ۳٫۳ می‌رساند و صفر شانسی هم ممکن است. تصمیم باید بر سیستم و صلاحیت تکیه کند.",r:"ISO 45001 §8.1.4; Poisson statistics",d:"HSEW-28",g:"C",w:14},{id:"e116",t:"عملیات هم‌زمان",q:"پیمانکار باید داخل واحد بازیابی آمونیاک جوشکاری کند در حالی که واحد در حال بهره‌برداری است. مناسب‌ترین اقدام پیش از شروع؟",o:["ارزیابی ریسک مشترک SIMOPS با مجوز کار، پایش پیوسته‌ی گاز و هماهنگی با اپراتور","JSA پیمانکار به‌تنهایی کافی است","توجیه عمومی ورود و صدور مجوز استاندارد","تعطیلی کامل کارخانه برای هر کار گرم"],a:0,e:"هم‌زمانی کار گرم و ماده‌ی قابل‌اشتعال/سمی خطر ویژه می‌سازد که تنها با ارزیابی مشترک و کنترل مجوز مدیریت می‌شود. تعطیلی کامل همیشه الزامی نیست.",r:"ISO 45001 §8.1.4; NFPA 51B",d:"HSEW-28",g:"C",w:14},{id:"e117",t:"نمونه‌گیری ممیزی",q:"ممیز از ۲۰۰ مجوز کار گرم ۱۰ نمونه برداشت و در یکی تست گاز ثبت نشده بود. بهترین اقدام؟",o:["اعلام ۱۰٪ عدم‌انطباق در کل مجوزها","نادیده گرفتن چون ۹۰٪ درست است","ثبت مشاهده بدون پیگیری","گسترش نمونه‌گیری ریسک‌محور تا معلوم شود موردی است یا سیستمی، سپس طبقه‌بندی"],a:3,e:"نمونه‌ی کوچک برای تعمیم درصدی کافی نیست ولی ایراد بدون پیگیری هم پذیرفتنی نیست. گسترش نمونه دامنه را روشن می‌کند.",r:"ISO 19011",d:"HSEW-14",g:"C",w:13},{id:"e118",t:"سطح HFACS",q:"سرپرست می‌دانست اپراتوری ۱۶ ساعت متوالی کار کرده و او را برای مانور اتوکلاو نگه داشت. تصمیم سرپرست در کدام سطح HFACS قرار می‌گیرد؟",o:["اعمال ناایمن","نظارت ناایمن","پیش‌شرط‌های اعمال ناایمن","تأثیرات سازمانی"],a:1,e:"تصمیم سرپرست برای عملیات نامناسب و اصلاح‌نکردن مشکل شناخته‌شده، نظارت ناایمن است. خستگی اپراتور خود پیش‌شرط است و اقدام او عمل ناایمن.",r:"Wiegmann & Shappell HFACS",g:"C",w:16},{id:"e119",t:"خستگی و کار بحرانی",q:"ساعت ۵ صبح، تعمیرکاری که حدود ۱۸ ساعت بیدار بوده برای قفل‌گذاری LOTO روی خط اسید آماده می‌شود. اقدام مناسب‌تر؟",o:["قهوه و ادامه‌ی کار","جایگزینی با فرد استراحت‌کرده و محدود کردن کار بحرانی در پایان شیفت طولانی","ثبت شفاهی خستگی و ادامه با مراقب","انجام کار با همکار دوم به‌عنوان ناظر"],a:1,e:"حدود ۱۸ ساعت بیداری از نظر عملکرد با الکل خون نزدیک ۰٫۰۵٪ قابل مقایسه است. قهوه و نظارت ظاهری نقص قضاوت و واکنش را جبران نمی‌کند.",r:"Williamson & Feyer 2000; API RP 755",d:"HSEW-22",g:"C",w:16},{id:"e120",t:"تخلف روتین",q:"اپراتورها مرحله‌ی ۷ رویه (اندازه‌گیری دما پیش از افزودن اسید) را همیشه جا می‌اندازند چون در زمان تعیین‌شده شدنی نیست. چه می‌کنید؟",o:["رویه و بار کار را با مشارکت اپراتورها بازنگری می‌کنم","آموزش مجدد رویه برای همه","اعمال انضباطی برای متخلفان","نصب تابلو هشدار کنار تجهیز"],a:0,e:"تخلف روتین ناشی از رویه‌ی غیرعملی نشانه‌ی ضعف طراحی کار است و آموزش یا تنبیه آن را تغییر نمی‌دهد. اصلاح رویه علت را برطرف می‌کند.",r:"Reason 1990; HSE HSG48",d:"HSEW-01",g:"C",w:16}],themes:[{title:"اسیدهای قوی، واکنش‌ها و اتوکلاو",summary:"این هفته: اسید سولفوریک و نیتریک، نشتی، واکنش‌های ناخواسته و تجهیزات فشاری انحلال",docs:["HSEW-03","HSEW-04","HSEW-09"]},{title:"آتش‌وانفجار، کار گرم و سیلندرها",summary:"این هفته: نیترات‌ها، هیدروژن، فرار حرارتی، کار گرم، جوشکاری و سیلندرهای گاز",docs:["HSEW-01","HSEW-02","HSEW-14","HSEW-15"]},{title:"آمونیاک، H2S و آشکارسازی گاز",summary:"این هفته: گازهای سمی در واحد بازیابی، آشکارسازها، حسگرها و نجات ایمن",docs:["HSEW-05","HSEW-08"]},{title:"مجوز کار و جداسازی انرژی (LOTO)",summary:"این هفته: مجوز کار، قفل‌گذاری، بلایند و راستی‌آزمایی ایزولاسیون",docs:["HSEW-22"]},{title:"نیکل و گرد قابل‌احتراق",summary:"این هفته: خطر انفجار گرد نیکل، نیکل کربونیل، سرطان‌زایی و نظافت ایمن",docs:["HSEW-05","HSEW-06"]},{title:"ایمنی فضای بسته",summary:"این هفته: شناسایی فضای مجوزدار، گازسنجی، تهویه، نگهبان و نجات",docs:[]},{title:"SDS/GHS، ماسک و دستکش",summary:"این هفته: خواندن SDS، کلمات هشدار، انتخاب ماسک و دستکش مناسب",docs:["HSEW-23"]},{title:"کار در ارتفاع و نردبان",summary:"این هفته: سلسله‌مراتب ارتفاع، هارنس، فضای آزاد سقوط و نردبان",docs:["HSEW-13","HSEW-18"]},{title:"بلندکردن، ماشین‌آلات و حمل بار",summary:"این هفته: جرثقیل، بند، لیفتراک، حفاظ ماشین، دیسک ساب، نویز و حمل دستی",docs:["HSEW-17","HSEW-26","HSEW-24","HSEW-25"]},{title:"حدود مواجهه، تهویه و بهداشت صنعتی",summary:"این هفته: TWA و STEL، نمونه‌برداری، تهویه موضعی و نظارت سلامت شغلی",docs:["HSEW-23"]},{title:"ایمنی برق و الکتریسیته ساکن",summary:"این هفته: قوس برق، ولتاژ باقی‌مانده، RCD، مناطق خطر و اتصال زمین",docs:["HSEW-19","HSEW-20","HSEW-21"]},{title:"ارزیابی ریسک: HAZOP، LOPA و Bow-tie",summary:"این هفته: روش‌های ارزیابی ریسک، سلسله‌مراتب کنترل، IPL و محدودیت ماتریس",docs:[]},{title:"تحقیق حادثه و فرهنگ عادلانه",summary:"این هفته: علت ریشه‌ای، حفظ شواهد، مدل‌های حادثه و گزارش‌دهی شبه‌حادثه",docs:["HSEW-27"]},{title:"شاخص‌ها، ممیزی و بهبود مستمر",summary:"این هفته: LTIFR و TRIR، شاخص پیشرو، نمونه‌گیری ممیزی و اقدام اصلاحی مؤثر",docs:[]},{title:"مدیریت تغییر و پیمانکاران",summary:"این هفته: MOC، تغییرات موقت، پیش‌ارزیابی پیمانکار و کارهای همزمان",docs:["HSEW-28"]},{title:"آمادگی اضطراری، ICS و چشم‌شو",summary:"این هفته: طرح اضطراری، فرماندهی حادثه، محل تجمع، تمرین و ایستگاه‌های شست‌وشو",docs:["HSEW-27"]},{title:"عوامل انسانی، آموزش و فرهنگ",summary:"این هفته: خستگی، خطا و تخلف، HFACS، شایستگی و ارزیابی اثربخشی آموزش",docs:[]}]};